    'files-clean': function (btn) {
      var count = Number(btn.getAttribute('data-count')) || 0;
      var bytes = Number(btn.getAttribute('data-bytes')) || 0;
      if (!count) { toast('先点「预览可清理」看看会删哪些文件', 'warn'); return; }
      openDialog({
        title: '清理归档文件',
        text: '这会真的删掉 ' + numText(count) + ' 个文件（共 ' + bytesText(bytes) + '），不可撤销；'
          + '删完台账里只留删除原因，文件本身找不回来。',
        confirmLabel: '确认清理',
        danger: true
      }).then(function (ok) {
        if (!ok) return null;
        return runWrite(btn, function () {
          return apiWrite('/api/files/cleanup', {}).then(function (data) {
            var d = data || {};
            var kept = Number(d.missing) || 0;
            var failed = Number(d.failed) || 0;
            toast('已清理 ' + numText(d.deleted) + ' 个文件（' + bytesText(d.bytes) + '）'
              + (kept ? '，' + numText(kept) + ' 个已不在盘上' : '')
              + (failed ? '，' + numText(failed) + ' 个失败' : ''), 'ok');
            libraryState.preview = null;
            return pageLoad('library', true);
          });
        });
      });
    },
