        ['私聊', cdTags((d.allowPrivate || []).map(function (q) { return 'QQ ' + q; }), '一个都没有'),
          (d.allowPrivate || []).length + ' 个 QQ'],
        ['私聊每日额度', cdNum(d.privateQuotaDailyMinutes) + ' 分钟', '用完当天就不再回私聊']
