        var reason = WAKE_REASON_LABELS[x.lastWakeReason] || x.lastWakeReason || '—';
        var freshN = freshCountOf(key, x);
        var preview = sessPreviewOf(x) || '还没有消息';
        var lastAt = Number((x && x.lastMessage && x.lastMessage.at) || 0);
