    for (var i = 0; i < sessRows.length; i += 1) {
      if (sessRows[i] && sessRows[i].key === target) { st = sessRows[i].st; break; }
    }
    var last = sessLastSeqOf(st);
    if (!last) return;
    var map = sessSeenMap();
    if ((Number(map[target]) || 0) >= last) return;
    map[target] = last;
