    var diff = Number(ms) - Date.now();
    if (!Number.isFinite(diff) || diff <= 0) return '马上';
    var mins = Math.round(diff / 60000);
    if (mins < 1) return '不到 1 分钟后';
    if (mins < 60) return '约 ' + mins + ' 分钟后';
