      + (roleText ? ' <span class="qdb-tag">' + esc(roleText) + '</span>' : '') + '</div>'
      + '<div class="qdb-member-id">' + esc(sub) + '</div></div>'
      + '<button class="qdb-member-note" type="button" data-write="member-note"'
      + ' data-user="' + esc(uid) + '" data-nick="' + esc(nick) + '"'
      + ' title="' + esc(note ? '改备注' : '给 TA 加备注') + '"'
      + ' aria-label="' + esc(note ? '改备注' : '加备注') + '">'
