    // 名字拿不到（后端还没给 label）时只留「群 + 群号」，别把同一串数字念两遍。
    var name = sessionNameOf(key);
    return '<div class="qdb-subhead qdb-sess-title">' + (name ? '<span class="qdb-sess-name">' + esc(name) + '</span>' : '')
