      if (isAnimatedMedia(item)) { out.push(animPlaceholderHtml(src, 'qdb-msg-img')); continue; }
      out.push('<img class="qdb-msg-img" loading="lazy" alt="聊天图片" data-zoom="' + esc(src) + '" src="' + esc(src) + '">');
