  // ── 文件库：stats + lists 统计；清理（先预览、确认后才删）+ 改分类 ──────────────
  // 两条写：POST /api/files/cleanup（先 { dryRun:true } 拿名单，确认后再 {} 真删）、
  // POST /api/files/category（把单个文件改成某个分类，空串=未分类）。
  // 预览名单只是「这一次停留」里的一张草稿：切走页面由 showView 调 libraryClearPreview 清掉、
  // 刷新由 pageLibrary 清掉；回来必须重新预览，免得拿半小时前的名单点确认，把刚上传的文件删了。
  var LIBRARY_PREVIEW_MAX = 50; // 明细只渲染前 50 条（名单可能上百条，全画出来会卡）
  var libraryState = {
    stats: null,     // GET /api/files/stats
    lists: null,     // GET /api/files/lists
    preview: null,   // { count, bytes, items:[{id,name,bytes,category,reason,createdAt}], nextRunAt }
    rules: null,     // GET /api/file-library/archive-rules（转存条件）
    folders: null,   // GET /api/files/folders（转存目录里的真实文件夹，点一下用资源管理器打开）
    assets: null,    // GET /api/library/assets（扫盘认出的「一件件素材」，L2 素材卡）
    batch: null,     // GET /api/library/batchfind（批量找号的进度，P3）
    filter: 'all',   // 素材筛选：all | no-booth | no-cover | suggested | bound（服务端过滤，切页后保留）
    query: '',       // 素材搜索词（服务端 q，标题 / 商品号 / 目录），输入 250ms 防抖
    sort: 'recent',  // 排序：recent | title | booth
    offset: 0,       // 「加载更多」翻到第几件（服务端 offset）
    loading: false,  // 正在拉这一页（防连点 + 按钮置灰）
    allTotal: 0,     // 未筛选时记下的全库件数（筛完一页时「全部」胶囊还显示真实总量）
    err: null        // 写失败的后端原文（errorBox 常驻在页面顶部，不只飘一条 toast）
  };

  // 没拿到 stats + lists 就不放行写按钮：数字不可信时删东西最危险。
  function libraryWriteDisabled() { return libraryState.stats && libraryState.lists ? '' : ' disabled'; }

  // 切走文件库时把预览草稿扔掉（旧名单可能已过时），顺手作废本页缓存，回来重新拉一版。
  function libraryClearPreview() {
    if (!libraryState.preview) return;
    libraryState.preview = null;
    if (pageState.library) pageState.library.loadedAt = 0;
  }

  function libraryStamp(value) {
    var n = typeof value === 'number' ? value : Date.parse(String(value || ''));
    if (!Number.isFinite(n) || n <= 0) return '—';
    var d = new Date(n);
    var p2 = function (v) { return (v < 10 ? '0' : '') + v; };
    return (d.getMonth() + 1) + '-' + p2(d.getDate()) + ' ' + p2(d.getHours()) + ':' + p2(d.getMinutes());
  }

  // 预览契约：{ wouldRemove:[{id,name,bytes,category,reason,createdAt}], wouldRemoveCount, wouldRemoveBytes, nextRunAt }。
  // 逐项兜成安全类型：旧后端 / 半截响应也不会渲染出 undefined 或 NaN。
  function libraryPreviewOf(data) {
    var rows = Array.isArray(data && data.wouldRemove) ? data.wouldRemove : [];
    var items = rows.map(function (row) {
      return {
        id: Number(row && row.id) || 0,
        name: String((row && row.name) || ''),
        bytes: Number(row && row.bytes) || 0,
        category: String((row && row.category) || ''),
        reason: String((row && row.reason) || ''),
        createdAt: (row && row.createdAt) || ''
      };
    });
    var count = Number(data && data.wouldRemoveCount);
    var bytes = Number(data && data.wouldRemoveBytes);
    return {
      count: Number.isFinite(count) ? count : items.length,
      bytes: Number.isFinite(bytes) ? bytes : items.reduce(function (sum, row) { return sum + row.bytes; }, 0),
      items: items,
      nextRunAt: (data && data.nextRunAt) || 0
    };
  }

  function libraryErrHtml() {
    if (!libraryState.err) return '';
    return '<div class="qdb-panel" style="margin-bottom:12px"><div class="qdb-panel-body">'
      + errorBox(libraryState.err, '写操作失败')
      + '<button class="qdb-btn qdb-btn-mini" type="button" data-write="files-dismiss-error">知道了</button>'
      + '</div></div>';
  }

  function libraryCleanBodyHtml() {
    var p = libraryState.preview;
    var dis = libraryWriteDisabled();
    var html = '<p class="qdb-hint">预览只把「过了保留期、该删的」列出来，不会动任何文件；确认后才会真删。</p>'
      + '<div class="qdb-actions" style="margin-top:8px">'
      + '<button class="qdb-btn qdb-btn-mini" type="button" data-write="files-preview"' + dis + '>预览可清理</button>'
      + (p && p.count
        ? '<button class="qdb-btn qdb-btn-mini qdb-btn-danger" type="button" data-write="files-clean" data-count="' + esc(p.count)
          + '" data-bytes="' + esc(p.bytes) + '"' + dis + '>确认清理这 ' + numText(p.count) + ' 个</button>'
        : '')
      + (p ? '<button class="qdb-btn qdb-btn-mini" type="button" data-write="files-preview-clear">取消预览</button>' : '')
      + '</div>';
    if (!p) return html;
    html += '<p class="qdb-hint" style="margin-top:8px">可清理 <strong>' + numText(p.count) + '</strong> 个，共 '
      + esc(bytesText(p.bytes)) + '；下次自动清理：' + esc(libraryStamp(p.nextRunAt)) + '</p>';
    if (!p.count || !p.items.length) return html + emptyLine('没有可清理的文件');
    var shown = p.items.slice(0, LIBRARY_PREVIEW_MAX);
    html += '<table class="qdb-table qdb-clean-table" style="margin-top:10px"><thead><tr>'
      + '<th>名称</th><th>分类</th><th>大小</th><th>原因</th><th>时间</th>'
      + '</tr></thead><tbody>'
      + shown.map(function (row) {
        return '<tr><td>' + esc(row.name || '—') + '</td>'
          + '<td>' + esc(row.category || '未分类') + '</td>'
          + '<td>' + esc(bytesText(row.bytes)) + '</td>'
          + '<td>' + esc(row.reason || '—') + '</td>'
          + '<td>' + esc(libraryStamp(row.createdAt)) + '</td></tr>';
      }).join('')
      + '</tbody></table>';
    if (p.count > shown.length) html += '<div class="qdb-empty">共 ' + numText(p.count) + ' 条，仅显示前 ' + numText(LIBRARY_PREVIEW_MAX) + '</div>';
    return html;
  }

  // ── 转存条件（config.json 的 fileArchive.rules）─────────────────────────
  // 规则怎么判、默认值是什么全在后端（src/file-archive/rules.js），前端只负责：
  // 把当前条件摆成人话、给一张能改的表单、保存后重画这一块。
  // 接口没就绪 / 只读时 fail-soft：面板显示一句原因，其它功能照旧。
  function archiveRulesData() { return libraryState.rules || null; }
  function archiveRulesOf() {
    var d = archiveRulesData();
    return (d && d.rules) || null;
  }
  function archiveRulesWritable() {
    var d = archiveRulesData();
    // 访客只读：接口虽然回 writable，但写请求会被 403，界面上别挂个「可改」骗人。
    return Boolean(d && d.writable) && !state.guestToken;
  }
  function archiveRuleTokens(text) {
    return String(text === null || text === undefined ? '' : text)
      .split(/[\s,，、]+/)
      .map(function (v) { return String(v).trim(); })
      .filter(Boolean);
  }
  function archiveRuleExts(list) {
    return (Array.isArray(list) ? list : [])
      .map(function (v) { return String(v).trim().replace(/^\./, '').toLowerCase(); })
      .filter(Boolean);
  }
  function archiveRuleField(rules, key, kind) {
    var v = rules ? rules[key] : undefined;
    if (kind === 'list') return Array.isArray(v) && v.length ? v.join(' ') : '';
    if (kind === 'number') return Number(v) > 0 ? String(Number(v)) : '0';
    return v === undefined || v === null ? '' : String(v);
  }
  // 面板上那排小标签：把规则翻成「允许 16 类 / 至少 10 KB / 只收名单里的 2 人」这种一眼能懂的话
  function archiveRulesChips(rules) {
    if (!rules) return '';
    var chips = [];
    var ext = archiveRuleExts(rules.extensions);
    var ban = archiveRuleExts(rules.excludeExtensions);
    chips.push(ext.length
      ? '允许 ' + numText(ext.length) + ' 类：' + ext.slice(0, 6).join(' ') + (ext.length > 6 ? ' …' : '')
      : '允许类型为空 = 谁都不收');
    if (ban.length) chips.push('排除：' + ban.slice(0, 6).join(' '));
    if (Number(rules.minKb) > 0) chips.push('至少 ' + numText(rules.minKb) + ' KB');
    if (Number(rules.maxMb) > 0) chips.push('最多 ' + numText(rules.maxMb) + ' MB');
    var inc = Array.isArray(rules.includeKeywords) ? rules.includeKeywords : [];
    var exc = Array.isArray(rules.excludeKeywords) ? rules.excludeKeywords : [];
    if (inc.length) chips.push('文件名需含：' + inc.slice(0, 4).join(' / '));
    if (exc.length) chips.push('文件名不含：' + exc.slice(0, 4).join(' / '));
    var mode = String(rules.senderMode || 'any');
    var senders = Array.isArray(rules.senders) ? rules.senders : [];
    if (mode === 'include') chips.push('只收名单里的 ' + numText(senders.length) + ' 人');
    else if (mode === 'exclude') chips.push('不收名单里的 ' + numText(senders.length) + ' 人');
    else chips.push('发送者不限');
    if (Number(rules.perHourMax) > 0) chips.push('每小时最多 ' + numText(rules.perHourMax) + ' 个');
    return chips.map(function (t) { return '<span class="qdb-chip">' + esc(t) + '</span>'; }).join('');
  }
  function archiveRulesPanelHtml() {
    var data = archiveRulesData();
    var dis = archiveRulesWritable() ? '' : ' disabled';
    var body;
    if (!data) {
      body = '<p class="qdb-hint" data-tone="warn">没取到当前条件（接口没就绪或者请求失败），先按后端默认口径转存。</p>';
    } else if (data.ok === false) {
      body = errorBox(String(data.error || '读取转存条件失败'), '转存条件');
    } else {
      body = '<p class="qdb-hint">' + esc(String(data.describe || '按默认口径：只收图片与压缩包，表情包不转存。')) + '</p>'
        + '<div class="qdb-chips" style="margin-top:8px">' + archiveRulesChips(archiveRulesOf()) + '</div>';
    }
    var actions = '<button class="qdb-btn qdb-btn-mini" type="button" data-write="archive-rules-edit"' + dis + '>编辑条件</button>';
      + '<button class="qdb-btn qdb-btn-mini" type="button" data-write="usage-roots-edit">工程扫描根</button>';
    return '<div class="qdb-panel" style="margin-bottom:16px"><div class="qdb-panel-head">'
      + '<h2 class="qdb-panel-title">转存条件</h2>'
      + '<span class="qdb-tag">' + (archiveRulesWritable() ? '可改' : '只读') + '</span>'
      + '<span class="qdb-panel-actions">' + actions + '</span>'
      + '</div><div class="qdb-panel-body">' + body + '</div></div>';
  }
  function loadArchiveRules() {
    return api('/api/file-library/archive-rules').then(function (data) {
      libraryState.rules = data || null;
    }).catch(function () {
      // 接口还没上线时不要让整页崩：置空，面板会显示原因，其它数据照常
      libraryState.rules = null;
    });
  }
  // 编辑弹层：一次性摆出全部条件，保存就是整份覆盖（后端负责校验与回落默认值）
  function archiveRulesEdit() {
    var data = archiveRulesData();
    if (!data || data.ok === false) { toast('还没取到当前条件，先点右上角「刷新」', 'warn'); return null; }
    if (!archiveRulesWritable()) { toast('当前是只读模式，改不了转存条件', 'warn'); return null; }
    var rules = archiveRulesOf() || {};
    var catalog = data.catalog || {};
    var all = Array.isArray(catalog.all) ? catalog.all : [];
    return openDialog({
      title: '转存条件',
      twoCol: true,
      text: '决定白名单群里什么样的文件会被自动转存到本地。类型留空表示一个都不收；关键词与发送者留空表示不限。',
      fields: [
        { name: 'extensions', label: '允许的类型', value: archiveRuleField(rules, 'extensions', 'list'), placeholder: all.slice(0, 10).join(' ') },
        { name: 'excludeExtensions', label: '排除的类型（优先于允许）', value: archiveRuleField(rules, 'excludeExtensions', 'list'), placeholder: '例如 exe apk' },
        { name: 'minKb', label: '最小体积（KB，0 = 不限）', value: archiveRuleField(rules, 'minKb', 'number'), placeholder: '0' },
        { name: 'maxMb', label: '最大体积（MB）', value: archiveRuleField(rules, 'maxMb', 'number'), placeholder: '2560' },
        { name: 'includeKeywords', label: '文件名必须含（空格分隔，空 = 不限）', value: archiveRuleField(rules, 'includeKeywords', 'list'), placeholder: '例如 模型 mod' },
        { name: 'excludeKeywords', label: '文件名不能含', value: archiveRuleField(rules, 'excludeKeywords', 'list'), placeholder: '例如 密码 失效' },
        { name: 'senderMode', label: '发送者', value: String(rules.senderMode || 'any'), options: [
          { value: 'any', label: '谁都可以' },
          { value: 'include', label: '只收名单里的' },
          { value: 'exclude', label: '不收名单里的' }
        ] },
        { name: 'senders', label: '发送者 QQ 号（空格分隔）', value: archiveRuleField(rules, 'senders', 'list'), placeholder: '例如 100000006' },
        { name: 'perHourMax', label: '每小时最多转存（0 = 不限）', value: archiveRuleField(rules, 'perHourMax', 'number'), placeholder: '0' }
      ],
      confirmLabel: '保存条件'
    }).then(function (values) {
      if (!values) return null;
      var next = {
        extensions: archiveRuleExts(archiveRuleTokens(values.extensions)),
        excludeExtensions: archiveRuleExts(archiveRuleTokens(values.excludeExtensions)),
        minKb: Math.max(0, Math.round(Number(values.minKb) || 0)),
        maxMb: Math.max(0, Math.round(Number(values.maxMb) || 0)),
        includeKeywords: archiveRuleTokens(values.includeKeywords),
        excludeKeywords: archiveRuleTokens(values.excludeKeywords),
        senderMode: String(values.senderMode || 'any'),
        senders: archiveRuleTokens(values.senders),
        perHourMax: Math.max(0, Math.round(Number(values.perHourMax) || 0))
      };
      return apiWrite('/api/file-library/archive-rules', { rules: next }).then(function (resp) {
        var d = resp || {};
        if (d.ok === false) { toast(String(d.error || '保存失败'), 'err'); return null; }
        if (libraryState.rules) {
          libraryState.rules.rules = d.rules || next;
          if (d.describe) libraryState.rules.describe = d.describe;
        }
        toast('转存条件已保存', 'ok');
        renderLibrary(pageHost('library'));
        return null;
      });
    });
  }

  // ── 文件库的「在电脑上的文件夹」：真实目录卡片，点一下用资源管理器打开 ──────
  var LIBRARY_FOLDER_ICON = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3.5 7.2A2.2 2.2 0 0 1 5.7 5h3.9c.6 0 1.1.2 1.5.6l1.2 1.2h6a2.2 2.2 0 0 1 2.2 2.2v7.8A2.2 2.2 0 0 1 18.3 19H5.7a2.2 2.2 0 0 1-2.2-2.2z"/></svg>';
  // 提示里显示完整路径：Windows 上目录分隔符是反斜杠，用 fromCharCode 拼，别在源码里写转义
  function folderFullPath(root, rel) {
    var sep = String.fromCharCode(92);
    var base = String(root || '');
    var tail = String(rel || '').split('/').filter(Boolean).join(sep);
    return tail ? base + sep + tail : base;
  }
  // 按群统计里的 groupId 只是数字，磁盘上的目录名是「群号_群名」，得从文件夹清单里认回来
  function groupFolderRel(groupId) {
    var gid = String(groupId || '');
    var d = libraryState.folders;
    var list = d && Array.isArray(d.folders) ? d.folders : [];
    var hit = list.filter(function (f) { return f.kind === 'group' && String(f.name || '').indexOf(gid) === 0; })[0];
    return hit ? String(hit.rel || '') : gid;
  }
  function libraryFoldersTag() {
    var d = libraryState.folders;
    if (!d || d.ok === false) return '读不到';
    if (d.missing) return '目录不存在';
    return numText((d.folders || []).length) + ' 个';
  }
  // ── 找号（BOOTH 素材库 P3）：按标题搜 BOOTH，人工确认后把号绑到这件素材上 ──
  // 为什么不一键自动绑：改色/衍生版本、同名不同店的情况太多，绑错号比不绑更糟。
  // 所以这里只做「把候选摆出来 + 默认帮选中证据最硬的那个」，最后一下永远是人点的。
  function cascadeConfirmText(a) { return String((a && (a.title || a.mainName)) || '这件素材'); }
  function openFindDialog(key, title) {
    if (!key) return;
    var mask = document.createElement('div');
    mask.className = 'qdb-dialog-mask';
    mask.setAttribute('role', 'dialog');
    mask.setAttribute('aria-modal', 'true');
    var box = document.createElement('div');
    box.className = 'qdb-dialog qdb-dialog-wide';
    box.innerHTML = '<h2 class="qdb-dialog-title">给「' + esc(title || key) + '」找 BOOTH 号</h2>'
      + '<p class="qdb-dialog-text" id="findHint">正在搜 BOOTH…（会按标题、店铺、封面指纹排；搜到几个就列几个，不替你决定）</p>'
      + '<div id="findList" class="qdb-find-list"><p class="qdb-hint">搜索中…</p></div>'
      + '<div class="qdb-dialog-foot">'
      + '<button class="qdb-btn" type="button" data-find-close>关掉</button>'
      + '<button class="qdb-btn" type="button" id="findRetry">重新搜</button>'
      + '</div>';
    mask.appendChild(box);
    document.body.appendChild(mask);
    function close() {
      document.removeEventListener('keydown', onKey);
      if (mask.parentNode) mask.parentNode.removeChild(mask);
    }
    function onKey(ev) { if (ev.key === 'Escape') close(); }
    document.addEventListener('keydown', onKey);
    mask.addEventListener('click', function (ev) {
      if (ev.target === mask) { close(); return; }
      var node = ev.target;
      if (!node || !node.closest) return;
      if (node.closest('[data-find-close]')) { close(); return; }
      if (node.closest('#findRetry')) { load(true); return; }
      var bindBtn = node.closest('[data-find-bind]');
      if (bindBtn) {
        var boothId = String(bindBtn.getAttribute('data-find-bind') || '');
        var candTitle = String(bindBtn.getAttribute('data-find-title') || '');
        if (!boothId) return;
        bindBtn.disabled = true;
        apiWrite('/api/library/bind', { key: key, boothId: boothId, title: candTitle }).then(function (resp) {
          var d = resp || {};
          if (d.ok === false) { toast(String(d.error || '绑定失败'), 'err'); bindBtn.disabled = false; return; }
          toast('已绑定 #' + boothId, 'ok');
          close();
          if (pageHost('library')) pageLoad('library', true);
        }).catch(function (error) {
          bindBtn.disabled = false;
          toast('绑定失败：' + ((error && error.message) || error), 'err', { sticky: true });
        });
      }
    });
    var hint = box.querySelector('#findHint');
    var list = box.querySelector('#findList');
    function paint(data) {
      if (!hint || !list) return;
      var cands = (data && Array.isArray(data.candidates)) ? data.candidates : [];
      hint.textContent = String((data && data.summary) || '没搜到东西') + (data && data.reason ? ' · ' + data.reason : '');
      hint.setAttribute('data-tone', data && data.auto ? 'ok' : 'warn');
      if (!cands.length) {
        list.innerHTML = '<p class="qdb-hint">没搜到候选：可能是标题里的装饰字太多，或者这件素材在 BOOTH 上已经下架。'
          + '可以只留名字里的英文/日文原名再搜一次。</p>';
        return;
      }
      list.innerHTML = cands.map(function (c, i) {
        // 本地图走 /api/files/raw 需要 ?token=；BOOTH 的封面是外链（https://booth.pximg.net/…），
        // 不能把 token 拼上去，否则 URL 直接坏掉（之前就是这里显示成破图）。
        var thumbSrc = c.thumbUrl
          ? withTokenQuery(c.thumbUrl)
          : '';
        var thumb = thumbSrc
          ? '<img class="qdb-find-thumb" src="' + esc(thumbSrc) + '" alt="" loading="lazy">'
          : '<span class="qdb-find-thumb qdb-asset-noimg">无图</span>';
        var meta = [c.shopName, c.price ? '¥' + numText(c.price) : ''].filter(Boolean).join(' · ');
        var reasons = (c.reasons || []).map(function (r) { return '<span class="qdb-find-tag">' + esc(r) + '</span>'; }).join('');
        var isPick = data && data.pick === String(c.boothId);
        return '<div class="qdb-find-row' + (i === 0 ? ' qdb-find-top' : '') + '">'
          + thumb
          + '<div class="qdb-find-main">'
          + '<div class="qdb-find-title"><span class="qdb-asset-id">#' + esc(c.boothId) + '</span>' + esc(c.title || '') + '</div>'
          + '<div class="qdb-find-meta">' + esc(meta) + (isPick ? ' · <b>默认帮你选这个</b>' : '') + '</div>'
          + '<div class="qdb-find-tags">' + reasons + '</div>'
          + '</div>'
          + '<div class="qdb-find-acts">'
          + '<button class="qdb-btn qdb-btn-mini' + (isPick ? ' qdb-btn-primary' : '') + '" type="button" data-find-bind="' + esc(c.boothId)
          + '" data-find-title="' + esc(c.title || '') + '">绑这个</button>'
          // 不在新标签里打开：全站只允许「点上游卡打开面板」那一处开新窗口，
          // 所以这里给的是复制商品页链接（复制有 toast），想看得自己去浏览器粘。
          + (c.itemUrl ? '<button class="qdb-btn qdb-btn-mini" type="button" data-copy="' + esc(c.itemUrl) + '" title="复制商品页链接">复制链接</button>' : '')
          + '</div></div>';
      }).join('');
    }
    var loading = false;
    function load(fresh) {
      if (loading) return;
      loading = true;
      if (hint) hint.textContent = '正在搜 BOOTH…';
      api('/api/library/find?key=' + encodeURIComponent(key) + (fresh ? '&fresh=1' : '')).then(function (data) {
        loading = false;
        paint(data || {});
      }).catch(function (error) {
        loading = false;
        if (hint) hint.textContent = '搜索失败：' + ((error && error.message) || error);
        if (list) list.innerHTML = '<p class="qdb-hint">可以先点「重新搜」再试一次；一直失败多半是这台机器连不上 booth.pm。</p>';
      });
    }
    load(false);
  }

  // ── 素材卡（L2）：GET /api/library/assets 已经由后端把「件」认好 ──────────────
  // 前端只负责画：封面、标题、号、文件数/体积，以及「在文件夹里看」。
  // ── 批量找号 / 绑建议号（P3） ─────────────────────────────────────────
  // 批量找号是「后台串行跑」：起任务立刻返回，页面自己轮询进度；跑完再刷新卡片。
  var libraryBatchTimer = 0;
  function libraryBatchText(text) {
    var nodes = document.querySelectorAll('[data-batch-text]');
    for (var i = 0; i < nodes.length; i += 1) nodes[i].textContent = text;
  }
  function libraryBatchPoll() {
    if (libraryBatchTimer) return;
    var tick = function () {
      libraryBatchTimer = window.setTimeout(function () {
        api('/api/library/batchfind').then(function (data) {
          var job = (data && data.job) || {};
          if (data && data.running) {
            libraryBatchText('正在找号… ' + numText(job.done || 0) + '/' + numText(job.total || 0));
            tick();
            return;
          }
          libraryBatchTimer = 0;
          libraryBatchText((data && data.text) || '批量找号结束');
          pageLoad('library', true);
        }).catch(function () {
          libraryBatchTimer = 0;
          libraryBatchText('进度没取到：刷新这一页看看结果');
        });
      }, 1200);
    };
    tick();
  }
  function libraryBatchFind(force) {
    return apiWrite('/api/library/batchfind', { force: force === true }).then(function (data) {
      if (data && data.queued) {
        toast('开始给 ' + numText(data.queued) + ' 件素材找号，进度在卡片上方');
        libraryBatchPoll();
      } else {
        toast('没有要重找的素材（都已经找过了）');
      }
      return pageLoad('library', true);
    });
  }
  function libraryBatchClear() {
    return apiWrite('/api/library/batchfind/clear', {}).then(function () {
      toast('已清空批量找号的结果（已绑定的号不受影响）');
      return pageLoad('library', true);
    });
  }
  function libraryBindSuggested(btn) {
    var key = String(btn.getAttribute('data-key') || '');
    var boothId = String(btn.getAttribute('data-booth') || '');
    var title = String(btn.getAttribute('data-title') || '');
    if (!key || !boothId) return Promise.resolve(null);
    return apiWrite('/api/library/bind', { key: key, boothId: boothId, title: title }).then(function () {
      toast('已绑定 #' + boothId);
      return pageLoad('library', true);
    });
  }

  // 批量找号：停止 / 重试 / 筛选。停止与重试都只发一次 API，进度仍走 libraryBatchPoll 那套轮询。
  function libraryBatchStop() {
    return apiWrite('/api/library/batchfind/stop', {}).then(function () {
      toast('已请求停止，正在跑的那件会先跑完');
      libraryBatchPoll();
      return pageLoad('library', true);
    });
  }
  // 「重试没找到的」= 现在既没有号、也没有建议的素材。后端 POST /api/library/batchfind 支持直接传
  // keys（显式传就不受「找过就跳过」影响，会重搜）；skipped 明细后端没有接口暴露，所以按「没结果」算。
  function libraryRetryKeys(list) {
    return (Array.isArray(list) ? list : []).filter(function (a) { return !a.boothId && !a.suggestion; })
      .map(function (a) { return a.key; });
  }
  function libraryRetrySkipped() {
    var keys = libraryRetryKeys((libraryState.assets || {}).assets);
    if (!keys.length) { toast('没有要重试的素材'); return Promise.resolve(null); }
    return apiWrite('/api/library/batchfind', { keys: keys }).then(function (data) {
      if (data && data.queued) { toast('开始重试 ' + numText(data.queued) + ' 件没找到号的素材'); libraryBatchPoll(); }
      else toast(String((data && (data.error || data.message)) || '后端没有开始这一轮'), 'warn');
      return pageLoad('library', true);
    });
  }
  // 服务端筛选 / 排序 / 分页（rules-backend 同批落地）。后端没接住参数时（响应没有 total 字段）
  // 退回前端过滤，至少不会让人看到明显不对的列表。
  var LIBRARY_FILTERS = [['all', '全部'], ['no-booth', '未认号'], ['no-cover', '无封面'], ['suggested', '待确认建议'], ['bound', '手动绑定'], ['with-password', '有解压码'], ['rj', '有 RJ']];
  var LIBRARY_SORTS = [['recent', '最近'], ['title', '按名字'], ['booth', '有号在前']];
  var LIBRARY_PAGE = 24;
  function libraryHasCover(a) { return Boolean(a.thumbUrl || a.coverUrl); }
