    return '<div class="qdb-actions" style="margin-top:10px">'
      + '<span class="qdb-batch-text">只显示前 ' + numText(shown) + ' 件（共 ' + numText(total) + ' 件）</span>'
      + '<button class="qdb-btn qdb-btn-mini" type="button" data-write="library-load-more"'
