      if (a && a.key) libraryCardCache[a.key] = a;
      // 封面优先级：本地预览图 → 已缓存的 BOOTH 展示图 → 「无预览」。
      // 令牌走查询串：<img> 带不了自定义头，控制台的图片接口都认 ?token=
      var coverSrc = a.thumbUrl || a.coverUrl || '';
