      + '<details style="margin-top:10px"><summary class="qdb-set-sub" style="cursor:pointer">展开看全部 '
      + numText(ctx.restartPaths.length) + ' 项</summary><div style="margin-top:8px">'
      + pathChips(ctx.restartPaths, '后端没回重启类路径') + '</div></details></div>'
      + (typeof libAutoExtractHtml === 'function' ? libAutoExtractHtml() : '')
      + '<div class="qdb-set-row" style="display:block">'
      + '<details><summary class="qdb-set-row-title" style="cursor:pointer">当前配置快照（只读 JSON）</summary>'
