          { name: 'url', label: 'SnowLuma 地址', value: snow.httpUrl || '', placeholder: 'http://127.0.0.1:3001' },
          { name: 'token', label: 'accessToken（留空=不改）', value: '', placeholder: '不回显', type: 'password' },
          { name: 'privateOpen', label: '私聊策略', value: setupState.view.privateOpen ? '1' : '0', options: [{ value: '0', label: '只回白名单里的私聊' }, { value: '1', label: '陌生人也回' }] }
