    qq_send_voice: '发了条语音',
    qq_send_tts: '发了条语音',
    qq_send_poke: '拍了拍「{to}」',
    qq_wait_for_messages: '等消息（静默 {quietMs} ms，超时 {timeoutMs} ms）',
    qq_search_history: '翻了下聊天记录：{q}',
    qq_recall: '翻了下聊天记录：{query}',
