      api('/api/socialV2/states').then(function (d) {
        var list = (d && Array.isArray(d.conversations) ? d.conversations : []).filter(function (c) { return c && c.key; });
        var pick = list.filter(function (c) { return /^private:/.test(String(c.key)); })[0] || list[0];
        if (pick) libPureFetchPartsFor(String(pick.key));
      }, function () {});
