    if (/HTTP 400/.test(msg)) return { tone: 'warn', text: '还没登录 BOOTH' };
    if (/rate_limited/.test(msg) || /限速/.test(msg)) return { tone: 'warn', text: '被 BOOTH 限速，稍后再点一次' };
    return { tone: 'err', text: libPurError(error) };
