        + '<div class="qdb-actions"><button class="qdb-btn qdb-btn-mini" type="button" data-write="library-purchases-import" data-booth="'
        + esc(d.boothId) + '">' + (d.stored ? '更新这件' : '导入这件') + '</button>'
