    var isUrl = /^https?:\/\//i.test(text);
    var isId = /^\d{5,9}$/.test(text);
    var body = (isUrl || isId) ? { url: isId ? 'https://booth.pm/ja/items/' + text : text } : { text: text };
    var host = byId('purResult');
    if (host) host.innerHTML = '<p class="qdb-hint">正在解析…（贴链接会抓一次商品页，可能几秒）</p>';
    return apiWrite('/api/library/purchases/resolve', body).then(function (d) {
      libPurState.hit = d;
      if (host) host.innerHTML = libPurHitHtml();
      return d;
    }, function (error) {
      libPurState.hit = null;
      var msg = libPurError(error);
      if (host) host.innerHTML = '<p class="qdb-hint" data-tone="warn">' + esc(msg) + '</p>';
      else toast(msg, 'err');
      return null;
    });
