function libBoothLoginApply(st) {
  libBoothLoginState.status = st || null;
  var state = String((st && st.state) || 'idle');
  var t = libBoothLoginText(st);
  libBoothLoginState.hint = t.text;
  libBoothLoginState.tone = t.tone;
  libBoothLoginPaint();
  if (state === 'succeeded') libBoothLoginSucceeded(st);
  if (libBoothLoginTerminal(state) && state !== 'succeeded') libBoothLoginStopPoll();
}
function libBoothLoginStatus() {
  return api('/api/library/purchases/login/status').then(function (d) {
    libBoothLoginApply(d && d.ok !== false ? d : { state: 'idle' });
    return d;
  }, function () {
    libBoothLoginStopPoll();
    libBoothLoginState.status = null;
    libBoothLoginState.hint = '后端还没上线自动登录（重启桥接后再试）';
    libBoothLoginState.tone = 'warn';
    libBoothLoginPaint();
    return null;
  });
}
function libBoothLoginPoll() {
  libBoothLoginStopPoll();
  libBoothLoginState.timer = window.setInterval(function () {
    var st = libBoothLoginState;
    var waited = libBoothLoginWaited(st.status);
    if (waited * 1000 > BOOTH_LOGIN_MAX_MS + 15000) {
      libBoothLoginStopPoll();
      st.hint = '等了 ' + numText(Math.round(waited / 60)) + ' 分钟还没登录成功，可以点按钮取消重来（浏览器窗口不会自动关）';
      st.tone = 'warn';
      libBoothLoginPaint();
      return;
    }
    libBoothLoginStatus();
  }, BOOTH_LOGIN_POLL_MS);
}
function libBoothLoginClick(btn) {
  var st = libBoothLoginState;
  var state = String((st.status && st.status.state) || 'idle');
  if (state === 'waiting' || state === 'launching') return libBoothLoginStop(btn);
  if (st.busy) return null;
  st.busy = true;
  st.syncedAt = 0;
  st.hint = '';
  st.tone = '';
  libBoothLoginPaint();
  return apiWrite('/api/library/purchases/login/start', {}).then(function (d) {
    st.busy = false;
    st.status = { state: String((d && d.state) || 'launching') };
    var t = libBoothLoginText(st.status);
    st.hint = t.text;
    st.tone = t.tone;
    libBoothLoginPaint();
    libBoothLoginStatus();
    libBoothLoginPoll();
    return d;
  }, function (error) {
    st.busy = false;
    var msg = String((error && error.message) || '');
    st.status = null;
    if (/HTTP 404/.test(msg) || /not found/i.test(msg)) {
      toast('后端还没上线自动登录（重启桥接后再试）', 'warn');
      st.hint = '后端还没上线自动登录（重启桥接后再试）'; st.tone = 'warn';
    } else if (/没找到能用的浏览器/.test(msg)) {
      toast('没找到能用的浏览器（Edge 或 Chrome），装一个再试', 'warn');
      st.hint = '没找到能用的浏览器（Edge 或 Chrome）'; st.tone = 'warn';
    } else {
      toast('打不开登录窗口：' + (msg.replace(/^HTTP \d+ · /, '') || '稍后再试'), 'err');
      st.hint = '打不开登录窗口：' + (msg.replace(/^HTTP \d+ · /, '') || '稍后再试'); st.tone = 'err';
    }
    libBoothLoginPaint();
    return null;
  });
}
function libBoothLoginStop(btn) {
  var st = libBoothLoginState;
  if (st.busy) return null;
  st.busy = true;
  libBoothLoginPaint();
  return apiWrite('/api/library/purchases/login/stop', {}).then(function () {
    st.busy = false;
    libBoothLoginStopPoll();
    st.status = { state: 'cancelled' };
    st.hint = '已取消登录';
    st.tone = '';
    libBoothLoginPaint();
    return true;
  }, function (error) {
    st.busy = false;
    var msg = String((error && error.message) || '');
    libBoothLoginStopPoll();
    st.status = { state: 'cancelled' };
    st.hint = /HTTP 409/.test(msg) ? '已取消登录' : '取消登录失败：' + (msg.replace(/^HTTP \d+ · /, '') || '稍后再试');
    st.tone = /HTTP 409/.test(msg) ? '' : 'warn';
    libBoothLoginPaint();
    return false;
  });
}
// 打开弹层：插按钮/提示区（幂等），有进行中的登录就接着显示并继续轮询
function libBoothLoginOpen() {
  var box = byId('purMask');
  if (!box) return;
  if (!byId('purLoginBtn')) {
    var syncBtn = byId('purSyncBtn');
    var btn = document.createElement('button');
    btn.className = 'qdb-btn qdb-btn-mini qdb-booth-login-btn';
    btn.type = 'button';
    btn.id = 'purLoginBtn';
    btn.setAttribute('data-write', 'library-booth-login');
    btn.textContent = '登录 BOOTH 自动同步';
    if (syncBtn && syncBtn.parentNode) syncBtn.parentNode.insertBefore(btn, syncBtn);
  }
  if (!byId('purLoginHint')) {
    var anchor = byId('purSyncState');
    var hint = document.createElement('p');
    hint.className = 'qdb-hint qdb-booth-login-hint';
    hint.id = 'purLoginHint';
    hint.hidden = true;
    if (anchor && anchor.parentNode) anchor.parentNode.insertBefore(hint, anchor.nextSibling);
  }
  libBoothLoginState.syncedAt = 0;
  libBoothLoginState.hint = '';
  libBoothLoginState.tone = '';
  libBoothLoginPaint();
  libBoothLoginStatus().then(function (d) {
    var state = String((d && d.ok !== false && d.state) || 'idle');
    if (state === 'launching' || state === 'waiting') libBoothLoginPoll();
    else libBoothLoginStopPoll();
  });
}
// 关闭弹层：只停轮询，不发 stop —— 浏览器窗口继续等你登录，下次打开还能接着看
function libBoothLoginClose() {
  libBoothLoginStopPoll();
  libBoothLoginState.busy = false;
}
// @client-fragment 素材库页「同步 BOOTH 已购」醒目入口：主按钮 + 进度小字 + 已购库入口 + 继续同步。
// 依赖：07f（libPurState 同步状态）、01-shell（toast/api/apiWrite/runWrite/openDialog）。
var LIB_SYNC_ENTRY_POLL_MS = 1500;
var libSyncEntryState = { timer: 0, status: null, recon: null, err: '', busy: false, note: '' };

function libSyncEntryBtn() { return document.getElementById('libProSyncBtn'); }
function libSyncEntryNoteEl() { return document.getElementById('libProSyncNote'); }

function libSyncEntryErrText(error) {
  var msg = String((error && error.message) || error || '');
  if (typeof netErrorText === 'function' && netErrorText(error)) return netErrorText(error);
  return msg.replace(/^HTTP \d+ · /, '') || '同步失败，稍后再试';
}

function libSyncEntryWhen(ts) {
  var n = Number(ts);
  if (!n || !isFinite(n)) return '';
  var d = new Date(n);
  if (isNaN(d.getTime())) return '';
  function p(x) { return (x < 10 ? '0' : '') + x; }
  return p(d.getMonth() + 1) + '-' + p(d.getDate()) + ' ' + p(d.getHours()) + ':' + p(d.getMinutes());
}

function libSyncEntryStats() {
  var st = libSyncEntryState.status || {};
  var rec = libSyncEntryState.recon || {};
  var stats = (rec.stats && typeof rec.stats === 'object') ? rec.stats : rec;
  return {
    lastSyncAt: Number(st.lastSyncAt || (st.lastResult && st.lastResult.finishedAt) || 0),
    purchased: Number(stats.purchased) || 0,
    missing: Number(stats.missing) || 0,
    hasRecon: typeof stats.purchased === 'number' || typeof stats.missing === 'number',
    stopped: String((st.lastResult && st.lastResult.stopped) || st.stopped || ''),
    pages: Number(st.totalPagesHint || (st.lastResult && st.lastResult.pages) || 0) || 0,
    page: st.running ? (Number(st.pages) || 0) : (Number((st.lastResult && st.lastResult.pages)) || 0),
    added: Number((st.progress && st.progress.added) || 0) || 0
  };
}

function libSyncEntryNoteText() {
  if (libSyncEntryState.err) return libSyncEntryState.err;
  var s = libSyncEntryStats();
  if (libSyncEntryState.busy || libPurState.syncing) {
    var head = s.page > 0 ? '同步中… 第 ' + numText(s.page) + ' 页' : '同步中… 正在准备';
    var tail = '';
    if (s.pages > 0) tail += '（共 ' + numText(s.pages) + ' 页）';
    if (s.added > 0) tail += '（已新增 ' + numText(s.added) + ' 件）';
    return head + tail;
  }
  var parts = [];
  if (s.lastSyncAt) parts.push('上次同步 ' + libSyncEntryWhen(s.lastSyncAt));
  if (s.purchased) parts.push('共 ' + numText(s.purchased) + ' 件已购');
  if (s.hasRecon) parts.push(s.missing ? '缺 ' + numText(s.missing) + ' 件' : '都齐了');
  if (s.stopped === 'rate_limited') parts.push('BOOTH 限速停了，点「继续同步」接着抓');
  else if (s.stopped === 'max_pages') parts.push('上次只同步了 ' + numText(s.pages || 1) + ' 页，点「继续同步」接着抓');
  return parts.join(' · ') || '还没同步过';
}

function libSyncEntryPaint() {
  var btn = libSyncEntryBtn();
  if (btn) {
    var s = libSyncEntryStats();
    var running = !!(libSyncEntryState.busy || libPurState.syncing);
    btn.disabled = false;
    if (running) btn.textContent = s.page > 0 ? '同步中… 第 ' + numText(s.page) + ' 页' : '同步中…';
    else btn.textContent = '⟳ 同步 BOOTH 已购';
  }
  var note = libSyncEntryNoteEl();
  if (note) {
    note.textContent = libSyncEntryNoteText();
    var s2 = libSyncEntryStats();
    note.setAttribute('data-tone', libSyncEntryState.err ? 'err' : (s2.stopped ? 'warn' : ''));
  }
  var resume = document.getElementById('libProSyncResume');
  if (resume) {
    var s3 = libSyncEntryStats();
    var show = !libSyncEntryState.busy && (s3.stopped === 'rate_limited' || s3.stopped === 'max_pages');
    resume.hidden = !show;
  }
}

function libSyncEntryLoad() {
  var jobs = [];
  jobs.push(api('/api/library/purchases/sync/status').then(function (d) {
    libSyncEntryState.status = (d && d.ok !== false) ? d : null;
    return null;
  }, function () { libSyncEntryState.status = null; return null; }));
  if (typeof api === 'function') {
    jobs.push(api('/api/library/reconcile').then(function (d) {
      libSyncEntryState.recon = (d && d.ok !== false) ? d : null;
      return null;
    }, function () { libSyncEntryState.recon = null; return null; }));
  }
  return Promise.all(jobs).then(function () {
    var hasStatus = !!libSyncEntryState.status;
    var hasRecon = !!libSyncEntryState.recon;
    libSyncEntryState.err = (!hasStatus && !hasRecon) ? '还没同步过' : '';
    libSyncEntryPaint();
    return null;
  });
}

function libSyncEntryStopPoll() {
  if (libSyncEntryState.timer) { window.clearInterval(libSyncEntryState.timer); libSyncEntryState.timer = 0; }
}

function libSyncEntryPoll() {
  libSyncEntryStopPoll();
  libSyncEntryState.timer = window.setInterval(function () {
    if (!libSyncEntryState.busy) { libSyncEntryStopPoll(); return; }
    api('/api/library/purchases/sync/status').then(function (d) {
      libSyncEntryState.status = (d && d.ok !== false) ? d : libSyncEntryState.status;
      libSyncEntryPaint();
    }, function () {});
  }, LIB_SYNC_ENTRY_POLL_MS);
}

function libSyncEntryRefreshLibrary() {
  if (typeof libProLoadFacets === 'function') libProLoadFacets();
  if (typeof libProLoad === 'function') libProLoad();
  if (typeof libProPaintSide === 'function') libProPaintSide();
}

function libSyncEntryAfter(result) {
  libSyncEntryState.busy = false;
  libSyncEntryStopPoll();
  var o = result || {};
  var added = Number(o.added) || 0, updated = Number(o.updated) || 0, unchanged = Number(o.unchanged) || 0, pages = Number(o.pages) || 0;
  if (o.stopped === 'rate_limited') {
    toast('BOOTH 限速，同步停了：剩余部分稍后点「继续同步」', 'warn');
  } else if (o.ok !== false) {
    toast('同步完成：新增 ' + numText(added) + ' · 更新 ' + numText(updated) + ' · 未变 ' + numText(unchanged)
      + (pages ? ' · 共 ' + numText(pages) + ' 页' : ''), 'ok');
  }
  libSyncEntryRefreshLibrary();
  return libSyncEntryLoad();
}

function libSyncEntryStart(btn) {
  if (libSyncEntryState.busy || libPurState.syncing) { toast('正在同步中，等这一轮跑完', 'warn'); return null; }
  return openDialog({
    title: '同步 BOOTH 已购',
    text: '从 BOOTH 已购清单全量同步？会逐页抓（约 1 分钟），只写本地已购台账，不动文件。',
    confirmLabel: '开始同步'
  }).then(function (ok) {
    if (!ok) return null;
    libSyncEntryState.busy = true;
    libSyncEntryState.err = '';
    libSyncEntryState.note = '同步中… 正在准备';
    libSyncEntryPaint();
    libSyncEntryPoll();
    return apiWrite('/api/library/purchases/sync', { dryRun: false }).then(function (r) {
      return libSyncEntryAfter(r);
    }, function (error) {
      libSyncEntryState.busy = false;
      libSyncEntryStopPoll();
      libSyncEntryState.err = '同步失败：' + libSyncEntryErrText(error);
      libSyncEntryPaint();
      return null;
    });
  });
}

function libSyncEntryResume(btn) {
  if (libSyncEntryState.busy || libPurState.syncing) { toast('正在同步中，等这一轮跑完', 'warn'); return null; }
  libSyncEntryState.busy = true;
  libSyncEntryState.err = '';
  libSyncEntryState.note = '继续同步中…';
  libSyncEntryPaint();
  libSyncEntryPoll();
  return apiWrite('/api/library/purchases/sync', { resume: true }).then(function (r) {
    var o = r || {};
    return libSyncEntryAfter(o);
  }, function (error) {
    var msg = String((error && error.message) || '');
    if (/HTTP 404/.test(msg) || /not found/i.test(msg)) {
      libSyncEntryState.busy = false;
      libSyncEntryState.err = '';
      toast('后端还没支持「继续同步」，先走普通同步', 'warn');
      return libSyncEntryStart(btn);
    }
    libSyncEntryState.busy = false;
    libSyncEntryStopPoll();
    libSyncEntryState.err = '同步失败：' + libSyncEntryErrText(error);
    libSyncEntryPaint();
    return null;
  });
}

function libSyncEntryHtml() {
  return '<span class="qdb-sync-entry" id="libProSyncEntry">'
    + '<button class="qdb-btn qdb-btn-primary" type="button" id="libProSyncBtn" data-write="library-sync-direct" title="从 BOOTH 抓已购清单并写进本地台账">⟳ 同步 BOOTH 已购</button>'
    + '<button class="qdb-btn qdb-btn-mini" type="button" id="libProSyncResume" data-write="library-purchases-sync-resume" hidden>继续同步</button>'
    + '<button class="qdb-btn qdb-btn-mini" type="button" id="libProPurchasesBtn" data-write="library-purchases-open" title="打开已购库（可解析、导入、刷新、移除）">已购库</button>'
    + '<span class="qdb-sync-note" id="libProSyncNote">还没同步过</span>'
    + '</span>';
}

function libSyncEntryMount() {
  var slot = document.getElementById('libProSyncSlot');
  if (!slot) return;
  if (!document.getElementById('libProSyncEntry')) slot.innerHTML = libSyncEntryHtml();
  libSyncEntryLoad();
}
// ── 背景音乐（设置 → 外观 → 背景音乐 + 顶栏音量） ─────────────────────────
// 三件事要说清楚，否则后面维护会踩同样的坑：
//
// 1. 默认曲子是 scripts/make-bgm.mjs 自己合成的（F 大调五声音阶、100 BPM、48 小节 ≈ 1 分 55 秒无缝循环），
//    旋律由本仓库编写，不引用任何现成作品 —— 所以随包分发没有版权问题，也不用挂署名。
// 2. 用户自己导入的音乐只存在这台机器的浏览器里（IndexedDB，不是 localStorage）：
//    一首 mp3 动辄 3~8 MB，localStorage 只有几 MB，塞进去必然 QuotaExceededError。
//    音频是二进制，IndexedDB 存 Blob 最省事，也能存大文件；不上传、不进仓库。
// 3. 浏览器的自动播放策略：没有用户交互前 play() 会被拒绝（NotAllowedError）。
//    所以「打开页面自动播」只能做到「尝试播放，被拒绝就等第一次点击/按键再播」，
//    设置页里如实写明这一点，不假装自动播放一定成功。
  var BGM_ON_KEY = 'qdb-bgm-on';
  var BGM_VOL_KEY = 'qdb-bgm-vol';
  var BGM_MUTE_KEY = 'qdb-bgm-mute';
  var BGM_SRC_KEY = 'qdb-bgm-src';
  var BGM_NAME_KEY = 'qdb-bgm-name';
  var BGM_DEFAULT_URL = '/bgm/default-tune.mp3';
  var BGM_DEFAULT_NAME = '默认轻快小调（自己合成的，无版权问题）';
  // 第二首内置曲：HALOFLUX 的主题曲，作者 Ryder191。按 PolyForm Noncommercial 1.0.0
  // 随包使用（仅限非商业），版权声明与署名见 public/bgm/HALOFLUX-LICENSE.txt。
  var BGM_HALO_URL = '/bgm/haloflux-sw421k.mp3';
  var BGM_HALO_NAME = 'HALOFLUX 主题曲（Ryder191 · 非商业）';
  var BGM_DB_NAME = 'qdb-bgm';
  var BGM_DB_STORE = 'tracks';
  var BGM_CUSTOM_KEY = 'custom';
  var BGM_MAX_BYTES = 24 * 1024 * 1024; // 24 MB：再大就不是「背景音乐」了

  var bgmAudio = null;
  var bgmObjectUrl = '';
  var bgmGestureArmed = false;
  var bgmLastError = '';

  function bgmStoreGet(key) {
    try {
      return window.localStorage ? window.localStorage.getItem(key) : null;
    } catch {
      return null;
    }
  }
  function bgmStoreSet(key, value) {
    try {
      if (value === null) window.localStorage.removeItem(key);
      else window.localStorage.setItem(key, value);
      return true;
    } catch {
      return false;
    }
  }

  function bgmOn() {
    var raw = bgmStoreGet(BGM_ON_KEY);
    return raw === null || raw === '' ? true : raw === '1'; // 默认开
  }
  function bgmMuted() { return bgmStoreGet(BGM_MUTE_KEY) === '1'; }
  function bgmVolume() {
    var raw = bgmStoreGet(BGM_VOL_KEY);
    if (raw === null || raw === '') return 40;
    var n = Number(raw);
    if (!Number.isFinite(n)) return 40;
    return Math.min(100, Math.max(0, Math.round(n)));
  }
  function bgmSource() {
    var raw = bgmStoreGet(BGM_SRC_KEY);
    if (raw === 'custom' || raw === 'halo') return raw;
    return 'default';
  }
  // 名字单独一处：顶栏 title、设置页状态、探针都用它，免得三处各写一遍「正在放什么」
  function bgmTrackName() {
    var src = bgmSource();
    if (src === 'custom') return bgmCustomName() || '自己的曲子';
    if (src === 'halo') return BGM_HALO_NAME;
    return BGM_DEFAULT_NAME;
  }
  function bgmCustomName() { return bgmStoreGet(BGM_NAME_KEY) || ''; }

  // ── IndexedDB：只存一个自定义曲子 ────────────────────────────────────
  function bgmDb() {
    return new Promise(function (resolve, reject) {
      if (!window.indexedDB) { reject(new Error('这个浏览器没有 IndexedDB')); return; }
      var req = window.indexedDB.open(BGM_DB_NAME, 1);
      req.onupgradeneeded = function () {
        var db = req.result;
        if (!db.objectStoreNames.contains(BGM_DB_STORE)) db.createObjectStore(BGM_DB_STORE);
      };
      req.onsuccess = function () { resolve(req.result); };
      req.onerror = function () { reject(req.error || new Error('打不开本地曲库')); };
    });
  }
  function bgmDbGet() {
    return bgmDb().then(function (db) {
      return new Promise(function (resolve, reject) {
        var tx = db.transaction(BGM_DB_STORE, 'readonly');
        var req = tx.objectStore(BGM_DB_STORE).get(BGM_CUSTOM_KEY);
        req.onsuccess = function () { resolve(req.result || null); };
        req.onerror = function () { reject(req.error || new Error('读不出来')); };
      });
    }).catch(function () { return null; });
  }
  function bgmDbPut(record) {
    return bgmDb().then(function (db) {
      return new Promise(function (resolve, reject) {
        var tx = db.transaction(BGM_DB_STORE, 'readwrite');
        var req = tx.objectStore(BGM_DB_STORE).put(record, BGM_CUSTOM_KEY);
        req.onsuccess = function () { resolve(true); };
        req.onerror = function () { reject(req.error || new Error('写不进去')); };
      });
    });
  }
  function bgmDbDelete() {
    return bgmDb().then(function (db) {
      return new Promise(function (resolve) {
        var tx = db.transaction(BGM_DB_STORE, 'readwrite');
        var req = tx.objectStore(BGM_DB_STORE).delete(BGM_CUSTOM_KEY);
        req.onsuccess = function () { resolve(true); };
        req.onerror = function () { resolve(false); };
      });
    }).catch(function () { return false; });
  }

  // ── 取当前该播的地址 ────────────────────────────────────────────────
  // 自定义曲子从 IndexedDB 读出来做成 objectURL；换曲子/移除时要 revoke 老的，不然内存里会堆。
  function bgmResolveUrl() {
    if (bgmSource() === 'halo') return Promise.resolve(BGM_HALO_URL);
    if (bgmSource() !== 'custom') return Promise.resolve(BGM_DEFAULT_URL);
    return bgmDbGet().then(function (rec) {
      var blob = rec && rec.blob;
      if (!blob) return BGM_DEFAULT_URL;
      if (bgmObjectUrl) { try { URL.revokeObjectURL(bgmObjectUrl); } catch {} bgmObjectUrl = ''; }
      try {
        bgmObjectUrl = URL.createObjectURL(blob);
        return bgmObjectUrl;
      } catch {
        return BGM_DEFAULT_URL;
      }
    });
  }

  function bgmNode() {
    if (bgmAudio) return bgmAudio;
    var audio = new Audio();
    audio.loop = true;
    audio.preload = 'auto';
    // 播放失败不再抛到控制台，交给 applyBgm 判断是不是「没交互被拦」
    audio.addEventListener('error', function () {
      bgmLastError = '这首曲子读不出来（文件坏了？）';
    });
    bgmAudio = audio;
    return audio;
  }

  // 第一次点击/按键/触摸时补一次播放：绕开浏览器的自动播放限制。
  // 只绑一次，成功播起来就把监听摘掉，别让一次点击触发多次。
  function bgmArmGesture() {
    if (bgmGestureArmed) return;
    bgmGestureArmed = true;
    var unlock = function () {
      bgmGestureArmed = false;
      ['pointerdown', 'keydown', 'touchstart'].forEach(function (name) {
        document.removeEventListener(name, unlock, true);
      });
      if (bgmOn() && !bgmMuted()) bgmPlayNow();
    };
    ['pointerdown', 'keydown', 'touchstart'].forEach(function (name) {
      document.addEventListener(name, unlock, true);
    });
  }

  function bgmPlayNow() {
    var audio = bgmNode();
    var p;
    try {
      p = audio.play();
    } catch (error) {
      bgmLastError = String((error && error.message) || error || '播放失败');
      return Promise.resolve(false);
    }
    if (!p || typeof p.then !== 'function') return Promise.resolve(true);
    return p.then(function () {
      bgmLastError = '';
      return true;
    }).catch(function (error) {
      var name = error && error.name;
      // NotAllowedError = 还没交互就被要求播放；这不是 bug，等第一次点击就行
      bgmLastError = name === 'NotAllowedError'
        ? '浏览器不允许自动播放：点一下页面任意位置就会响'
        : String((error && error.message) || error || '播放失败');
      bgmArmGesture();
      return false;
    });
  }

  // 把「开关 / 音量 / 静音 / 曲源」一次性落到 audio 与界面
  function applyBgm() {
    var on = bgmOn();
    var root = document.documentElement;
    if (root) root.dataset.bgm = on ? 'on' : 'off';
    bgmSyncChrome();
    if (!on) {
      if (bgmAudio) {
        try { bgmAudio.pause(); } catch {}
      }
      return Promise.resolve();
    }
    return bgmResolveUrl().then(function (url) {
      var audio = bgmNode();
      if (url && audio.src !== new URL(url, window.location.href).href) {
        audio.src = url;
        audio.load();
      }
      audio.volume = Math.min(1, Math.max(0, bgmVolume() / 100));
      audio.muted = bgmMuted();
      if (audio.muted || bgmVolume() === 0) {
        // 静音时不必真的 decode：先播着（muted 的播放也被允许），再恢复时直接出声
        return bgmPlayNow();
      }
      return bgmPlayNow();
    });
  }

  // ── 顶栏控件（右上角的喇叭 + 音量条） ───────────────────────────────
  // 图标：经典小喇叭 + 3 个外扩圆弧；静音时叠一条斜杠（SVG 里两组线，用 data-muted 切）。
  function bgmIconSvg() {
    // 喇叭本体 + 外扩三道弧（经典音量图标）；静音时叠一条从左上到右下的斜杠。
    // 弧的半径逐道放大、圆心都落在喇叭口右侧，这样看着是「声音在往外扩」而不是三个括号。
    return '<svg class="qdb-bgm-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false">'
      + '<path class="qdb-bgm-speaker" d="M4 9.4h3.2L11.4 5.6v12.8L7.2 14.6H4z"/>'
      + '<path class="qdb-bgm-wave qdb-bgm-wave1" d="M13.6 9.6a3.4 3.4 0 0 1 0 4.8"/>'
      + '<path class="qdb-bgm-wave qdb-bgm-wave2" d="M16 7.2a6.5 6.5 0 0 1 0 9.6"/>'
      + '<path class="qdb-bgm-wave qdb-bgm-wave3" d="M18.4 4.9a9.4 9.4 0 0 1 0 14.2"/>'
      + '<path class="qdb-bgm-slash" d="M4.6 19.8 19.4 4.2"/>'
      + '</svg>';
  }

  function bgmTopbarHtml() {
    return '<div class="qdb-bgm-ctl" id="bgmCtl"' + (bgmOn() ? '' : ' hidden') + '>'
      + '<button class="qdb-icon-btn qdb-bgm-mute" id="bgmMuteBtn" type="button" aria-pressed="' + (bgmMuted() ? 'true' : 'false')
      + '" aria-label="' + (bgmMuted() ? '取消静音' : '静音') + '" title="' + (bgmMuted() ? '取消静音' : '静音') + '">'
      + bgmIconSvg() + '</button>'
      + '<input class="qdb-bgm-vol" id="bgmVolTop" type="range" min="0" max="100" step="1" value="' + bgmVolume() + '"'
      + ' aria-label="背景音乐音量" title="背景音乐音量 ' + bgmVolume() + '%">'
      + '</div>';
  }

  // 顶栏位置：挂在深浅色按钮前面（同一行靠右），和状态 chip 分开，窄屏也不会把 chips 挤走
  function bgmMountTopbar() {
    var header = document.querySelector('.qdb-topbar');
    if (!header) return;
    var existing = document.getElementById('bgmCtl');
    if (existing) return;
    var themeBtn = document.getElementById('themeToggle');
    var wrap = document.createElement('div');
    wrap.innerHTML = bgmTopbarHtml();
    var node = wrap.firstElementChild;
    if (!node) return;
    if (themeBtn && themeBtn.parentNode === header) header.insertBefore(node, themeBtn);
    else header.appendChild(node);
    bgmBindTopbar();
  }

  function bgmBindTopbar() {
    var mute = byId('bgmMuteBtn');
    if (mute) mute.addEventListener('click', function () { bgmToggleMute(); });
    var vol = byId('bgmVolTop');
    if (vol) vol.addEventListener('input', function () {
      bgmSetVolume(Number(vol.value) || 0);
    });
  }

  // ── 设置页里那一行 ──────────────────────────────────────────────────
  function bgmStatusText() {
    if (!bgmOn()) return '<span class="qdb-bgm-state">已关闭：顶栏的音量条也会跟着消失</span>';
    var name = bgmTrackName();
    var tail = bgmLastError ? '（' + esc(bgmLastError) + '）' : '';
    return '<span class="qdb-bgm-state" data-on="1">正在放：' + esc(name) + tail + '</span>';
  }

  // 三选一：默认小调 / HALOFLUX 主题曲 / 自己的曲子
  function bgmTrackPickerHtml() {
    var src = bgmSource();
    var items = [
      { id: 'default', label: '默认轻快小调' },
      { id: 'halo', label: 'HALOFLUX 主题曲' },
      { id: 'custom', label: '自己的曲子' }
    ];
    var html = '<div class="qdb-bgm-tracks" role="group" aria-label="选择背景音乐">';
    for (var i = 0; i < items.length; i += 1) {
      var it = items[i];
      html += '<button class="qdb-bgm-track" type="button" data-bgm-track="' + it.id + '"'
        + ' aria-pressed="' + (src === it.id ? 'true' : 'false') + '"'
        + (src === it.id ? ' data-on="1"' : '') + '>' + esc(it.label) + '</button>';
    }
    return html + '</div>';
  }

  function bgmRowHtml() {
    var on = bgmOn();
    var muted = bgmMuted();
    var vol = bgmVolume();
    var custom = bgmSource() === 'custom';
    return '<div class="qdb-set-row qdb-bgm-row"><div class="qdb-set-row-main">'
      + '<p class="qdb-set-row-title">背景音乐</p>'
      + '<p class="qdb-set-sub">打开控制台就自动放一段轻音乐。默认曲是本工具自己合成的（F 大调五声音阶、约 1 分 55 秒无缝循环，'
      + '旋律由本仓库编写，没有版权问题）；也可以换成自己的曲子，音频只存在这台机器的浏览器里，不上传。'
      + '浏览器的自动播放策略可能要求先点一下页面才出声 —— 被拦下时点任意位置即可。</p>'
      + bgmTrackPickerHtml()
      + '<div class="qdb-bgm-tools">'
      + '<button class="qdb-btn qdb-btn-mini" type="button" data-bgm-action="pick">' + (custom ? '换一首' : '导入自己的曲子') + '</button>'
      + (custom ? '<button class="qdb-btn qdb-btn-mini" type="button" data-bgm-action="default">用回默认</button>' : '')
      + bgmStatusText()
      + '</div></div>'
      + '<div class="qdb-set-row-ctl qdb-bgm-ctl-wrap">'
      + '<div class="qdb-bgm-line"><label class="qdb-switch" for="setBgmOn">'
      + '<input type="checkbox" id="setBgmOn"' + (on ? ' checked' : '') + '>'
      + '<span class="qdb-switch-track"><span class="qdb-switch-dot"></span></span>'
      + '<span id="setBgmOnState">' + (on ? '开' : '关') + '</span></label></div>'
      + '<div class="qdb-bgm-line"><span class="qdb-bgm-label">音量</span>'
      + '<input class="qdb-range qdb-bgm-range" id="setBgmVol" type="range" min="0" max="100" step="1" value="' + vol + '"'
      + (on ? '' : ' disabled') + ' aria-label="背景音乐音量">'
      + '<span class="qdb-num-wrap"><input class="qdb-num qdb-bgm-val" id="setBgmVolVal" type="number" min="0" max="100" step="1" value="' + vol + '"'
      + (on ? '' : ' disabled') + ' aria-label="背景音乐音量百分比"><span class="qdb-num-unit">%</span></span>'
      + '<button class="qdb-btn qdb-btn-mini qdb-bgm-mute2" type="button" id="setBgmMute" data-bgm-action="mute"'
      + ' aria-pressed="' + (muted ? 'true' : 'false') + '"' + (on ? '' : ' disabled') + '>' + (muted ? '取消静音' : '静音') + '</button>'
      + '</div></div></div>';
  }

  // 设置页与顶栏是同一份状态：任何一边改动，两边一起刷（这是用户明确要求的「同步」）
  function bgmSyncChrome() {
    var on = bgmOn();
    var muted = bgmMuted();
    var vol = bgmVolume();
    var ctl = byId('bgmCtl');
    if (ctl) ctl.hidden = !on;
    var mute = byId('bgmMuteBtn');
    if (mute) {
      mute.setAttribute('aria-pressed', muted ? 'true' : 'false');
      mute.setAttribute('aria-label', muted ? '取消静音' : '静音');
      mute.setAttribute('title', muted ? '取消静音' : '静音');
      mute.setAttribute('data-muted', muted ? '1' : '0');
    }
    var top = byId('bgmVolTop');
    if (top && document.activeElement !== top) top.value = String(vol);
    var sw = byId('setBgmOn');
    if (sw) sw.checked = on;
    var swState = byId('setBgmOnState');
    if (swState) swState.textContent = on ? '开' : '关';
    var range = byId('setBgmVol');
    if (range) {
      range.disabled = !on;
      if (document.activeElement !== range) range.value = String(vol);
    }
    var val = byId('setBgmVolVal');
    if (val) {
      val.disabled = !on;
      if (document.activeElement !== val) val.value = String(vol);
    }
    var mute2 = byId('setBgmMute');
    if (mute2) {
      mute2.disabled = !on;
      mute2.setAttribute('aria-pressed', muted ? 'true' : 'false');
      mute2.textContent = muted ? '取消静音' : '静音';
    }
    var state = document.querySelector('.qdb-bgm-state');
    if (state && state.parentNode) {
      var wrap = document.createElement('span');
      wrap.innerHTML = bgmStatusText();
      state.parentNode.replaceChild(wrap.firstElementChild, state);
    }
  }

  function bgmSetVolume(value) {
    var vol = Math.min(100, Math.max(0, Math.round(Number(value) || 0)));
    bgmStoreSet(BGM_VOL_KEY, String(vol));
    // 拖到 0 视同静音、拖回来自动取消静音 —— 「音量条到底」和「按了静音」用户想的是同一件事
    if (vol === 0 && !bgmMuted()) bgmStoreSet(BGM_MUTE_KEY, '1');
    if (vol > 0 && bgmMuted()) bgmStoreSet(BGM_MUTE_KEY, null);
    if (bgmAudio) {
      bgmAudio.volume = Math.min(1, vol / 100);
      bgmAudio.muted = bgmMuted();
    }
    bgmSyncChrome();
    if (bgmOn() && bgmAudio && bgmAudio.paused) bgmPlayNow();
  }

  function bgmToggleMute() {
    var next = !bgmMuted();
    bgmStoreSet(BGM_MUTE_KEY, next ? '1' : null);
    if (bgmAudio) bgmAudio.muted = next;
    bgmSyncChrome();
    if (bgmOn() && !next && bgmAudio && bgmAudio.paused) bgmPlayNow();
  }

  function bgmSetTrack(id) {
    if (id === 'custom') {
      // 还没有自己的曲子时，点这一档就是「去选一首」，而不是先切成空的自定义
      bgmDbGet().then(function (rec) {
        if (rec && rec.blob) {
          bgmStoreSet(BGM_SRC_KEY, 'custom');
          return applyBgm();
        }
        bgmPickFile();
        return null;
      }).then(function () { bgmRepaintRow(); });
      return;
    }
    bgmStoreSet(BGM_SRC_KEY, id === 'halo' ? 'halo' : null);
    if (id !== 'custom') bgmStoreSet(BGM_NAME_KEY, null);
    applyBgm();
    bgmRepaintRow();
    toast(id === 'halo' ? '已换成 HALOFLUX 主题曲（Ryder191，非商业使用）' : '已换回默认曲子', 'ok');
  }

  function bgmSetEnabled(on) {
    bgmStoreSet(BGM_ON_KEY, on ? '1' : '0');
    applyBgm();
  }

  // 选曲子：临时 input[type=file]，跟自定义背景一个套路（用完即弃，不留常驻控件）
  function bgmPickFile() {
    var input = document.createElement('input');
    input.type = 'file';
    input.accept = 'audio/*,.mp3,.m4a,.ogg,.wav,.flac,.aac';
    input.style.display = 'none';
    input.addEventListener('change', function () {
      var file = input.files && input.files[0];
      if (file) bgmImportFile(file);
      if (input.parentNode) input.parentNode.removeChild(input);
    });
    document.body.appendChild(input);
    input.click();
  }

  function bgmImportFile(file) {
    if (!file) return;
    var type = String(file.type || '');
    if (type && type.indexOf('audio/') !== 0) { toast('只支持音频文件（mp3 / m4a / ogg / wav）', 'warn'); return; }
    if (file.size > BGM_MAX_BYTES) {
      toast('这首太大（超过 ' + (BGM_MAX_BYTES / 1024 / 1024) + ' MB），换首小一点的', 'warn', { sticky: true });
      return;
    }
    bgmDbPut({ blob: file, name: file.name, size: file.size, type: type, at: Date.now() }).then(function () {
      bgmStoreSet(BGM_SRC_KEY, 'custom');
      bgmStoreSet(BGM_NAME_KEY, file.name);
      if (bgmOn()) bgmStoreSet(BGM_ON_KEY, '1');
      return applyBgm();
    }).then(function () {
      bgmRepaintRow();
      toast('已换成：' + file.name + '（' + (file.size / 1024 / 1024).toFixed(1) + ' MB，只在本机）', 'ok');
    }).catch(function (error) {
      var name = (error && error.name) || '';
      toast(name === 'QuotaExceededError'
        ? '本地空间不够存这首曲子，换首小一点的'
        : '这首曲子存不进去（' + String((error && error.message) || error) + '）', 'err', { sticky: true });
    });
  }

  // 只重画「背景音乐」这一行：整块 setBody 重画会把毛玻璃/背景那些监听一起换掉（07 踩过的坑）
  function bgmRepaintRow() {
    var host = byId('setBody');
    var row = host && host.querySelector ? host.querySelector('.qdb-bgm-row') : null;
    if (!row || !row.parentNode) return;
    var wrap = document.createElement('div');
    wrap.innerHTML = bgmRowHtml();
    var next = wrap.firstElementChild;
    if (!next) return;
    row.parentNode.replaceChild(next, row);
    bgmBindRow();
  }

  function bgmBindRow() {
    var host = byId('setBody');
    var row = host && host.querySelector ? host.querySelector('.qdb-bgm-row') : null;
    if (!row || row.getAttribute('data-bound') === '1') return;
    row.setAttribute('data-bound', '1');
    var sw = row.querySelector('#setBgmOn');
    if (sw) sw.addEventListener('change', function () { bgmSetEnabled(sw.checked); });
    var range = row.querySelector('#setBgmVol');
    if (range) range.addEventListener('input', function () { bgmSetVolume(range.value); });
    // 数字框：边打边生效；失焦/回车夹到 0~100（bgmSetVolume 里还会顺带处理 0=静音）
    var num = row.querySelector('#setBgmVolVal');
    if (num) {
      num.addEventListener('input', function () { if (String(num.value).trim() !== '') bgmSetVolume(num.value); });
      num.addEventListener('change', function () {
        var v = Math.min(100, Math.max(0, Math.round(Number(num.value) || 0)));
        num.value = String(v);
        bgmSetVolume(v);
      });
    }
    row.addEventListener('click', function (ev) {
      var trackBtn = ev.target && ev.target.closest ? ev.target.closest('[data-bgm-track]') : null;
      if (trackBtn) { bgmSetTrack(trackBtn.getAttribute('data-bgm-track')); return; }
      var btn = ev.target && ev.target.closest ? ev.target.closest('[data-bgm-action]') : null;
      if (!btn) return;
      var action = btn.getAttribute('data-bgm-action');
      if (action === 'pick') { bgmPickFile(); return; }
      if (action === 'mute') { bgmToggleMute(); return; }
      if (action === 'default') {
        bgmDbDelete().then(function () {
          bgmStoreSet(BGM_SRC_KEY, null);
          bgmStoreSet(BGM_NAME_KEY, null);
          return applyBgm();
        }).then(function () {
          bgmRepaintRow();
          toast('已换回默认曲子', 'ok');
        });
      }
    });
  }

  // 设置页换组时会整块重画（bindBgmControls 由 04 的 bindSettingsControls 调用）
  function bindBgmControls() { bgmBindRow(); }

// 自检/排障用的只读探针：控制台里能看到「现在到底在放什么、有没有被浏览器拦」。
// 只读、不改状态，也不把内部对象暴露出去（只回一份快照）。
window.__qdbBgmState = function () {
  return {
    on: bgmOn(),
    muted: bgmMuted(),
    volume: bgmVolume(),
    source: bgmSource(),
    name: bgmTrackName(),
    paused: bgmAudio ? bgmAudio.paused : null,
    currentTime: bgmAudio ? Number(bgmAudio.currentTime.toFixed(2)) : null,
    src: bgmAudio ? String(bgmAudio.src || '').split('/').pop() : '',
    error: bgmLastError
  };
};

// 启动：先把顶栏控件挂上（开关为关时它是 hidden），再按上次的偏好播放。
// 放在本片段末尾：上面的常量在这里才赋过值，若从 05 的启动段调用，var 提升会让
// BGM_ON_KEY 还是 undefined，getItem(undefined) 恒 null，开关状态就永远是默认值。
bgmMountTopbar();
applyBgm();
// ── 仪表盘顶上的「数据环」（只给「数据环 HUD」那套皮肤用） ───────────────────
// 观感来自 HALOFLUX by Ryder191（RYDER CODE / Ms MAIKEBAIs CAT）
// https://github.com/Ryder191/haloflux ，按 PolyForm Noncommercial 1.0.0 使用：
// 仅限非商业，源码/作品署名见 public/bgm/HALOFLUX-LICENSE.txt。这一版是照那套
// 视觉语言（斜置数据环带 + 向外扩散的光束 + 左侧网线 + 扫描线）重画的，不是逐行移植。
//
// 三个工程约束（踩过就知道为什么这么写）：
// 1. 静态部分（环带、数据块、左侧网线）只画一次，存进离屏 canvas；每帧只做
//    「贴图 + 旋转 + 光束 + 扫描线」。全部每帧重画会在弱机上掉到 20fps 以下。
// 2. 皮肤不在这套时（data-skin != halo）整个停掉 rAF，只留一张静帧；页面切走、
//    标签页隐藏时也停，别为了背景动画一直烧 CPU。
// 3. 系统开了「减少动态」就只画静帧，不跑 rAF —— 前庭敏感的人会被旋转的东西恶心到。
  var ringCv = null;
  var ringCtx = null;
  var ringW = 0;
  var ringH = 0;
  var ringDpr = 1;
  var ringRaf = 0;
  var ringTimer = 0;
  var ringMounted = false;
  var ringStill = null;   // 静态层：环带 + 数据块 + 网线
  var ringBeams = [];     // 向外扫的光束
  var ringStrands = [];   // 右侧那排平行流线（静态在底图上，高光沿它跑）
  var ringT0 = 0;
  var ringLast = 0;
  var ringBeat = 0;
  var ringSkinOn = false;
  var ringHero = null;
  var ringFull = false;   // 全屏背景模式（Halo 皮肤下画布铺满整页）

  var RING_BEAT_MS = 620;         // 节拍：比真实音乐慢一点，像「呼吸」而不是「打鼓」
  var RING_TILT = -0.36;          // 环带倾斜角（弧度）
  var RING_SQUASH = 0.46;         // 椭圆压扁比：压得越扁越像从侧面看一个圆环
  var RING_DPR_CAP = 2;

  function ringReduced() {
    return typeof window.matchMedia === 'function' && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  }

  // 环带上的「数据块」：用固定种子的伪随机，刷新后纹理不变（否则每次进页面都在跳）
  function ringRnd(seed) {
    var x = Math.sin(seed * 12.9898) * 43758.5453;
    return x - Math.floor(x);
  }

  function ringBuildStill() {
    var c = document.createElement('canvas');
    c.width = Math.max(1, Math.round(ringW * ringDpr));
    c.height = Math.max(1, Math.round(ringH * ringDpr));
    var x = c.getContext('2d');
    x.setTransform(ringDpr, 0, 0, ringDpr, 0, 0);
    x.fillStyle = '#050608';
    x.fillRect(0, 0, ringW, ringH);

    // 全屏背景模式：整页都是这张图，所以先铺一层「HUD 底纹」——
    // 细网格 + 竖向码条 + 两团冷暖光晕，让卡片后面也有东西可透，而不是一块纯黑。
    if (ringFull) {
      x.save();
      x.globalAlpha = 0.5;
      x.strokeStyle = 'rgba(226,232,244,.05)';
      x.lineWidth = 1;
      for (var gx = 0; gx < ringW; gx += 64) {
        x.beginPath(); x.moveTo(gx + 0.5, 0); x.lineTo(gx + 0.5, ringH); x.stroke();
      }
      x.strokeStyle = 'rgba(226,232,244,.035)';
      for (var gy = 0; gy < ringH; gy += 64) {
        x.beginPath(); x.moveTo(0, gy + 0.5); x.lineTo(ringW, gy + 0.5); x.stroke();
      }
      // 竖向码条：高低不齐的短线簇，像屏幕边缘滚动的寄存器
      for (var ci = 0; ci < 260; ci += 1) {
        var cxx = ringRnd(ci * 1.7) * ringW;
        var cyy = ringRnd(ci * 3.3) * ringH;
        var ch = 6 + ringRnd(ci * 5.1) * 46;
        var cw = 1 + ringRnd(ci * 7.7) * 2.4;
        var ca = 0.07 + ringRnd(ci * 2.3) * 0.26;
        var warm = ringRnd(ci * 9.1) < 0.12;
        x.fillStyle = warm ? 'rgba(240,166,198,' + ca.toFixed(3) + ')' : 'rgba(226,232,244,' + ca.toFixed(3) + ')';
        x.fillRect(cxx, cyy, cw, ch);
      }
      // 底光：全屏模式下卡片会盖住大半个画面，只靠细线透过模糊就什么都看不见了。
      // 先铺两层「大面积柔光带」（横向 + 斜向），保证卡片背后也有明暗层次。
      x.save();
      var bandG = x.createLinearGradient(0, ringH * 0.18, 0, ringH * 0.92);
      bandG.addColorStop(0, 'rgba(210,226,240,0)');
      bandG.addColorStop(0.32, 'rgba(210,226,240,.10)');
      bandG.addColorStop(0.52, 'rgba(226,238,248,.16)');
      bandG.addColorStop(0.74, 'rgba(196,214,232,.08)');
      bandG.addColorStop(1, 'rgba(210,226,240,0)');
      x.fillStyle = bandG;
      x.fillRect(0, ringH * 0.18, ringW, ringH * 0.74);
      var diag = x.createLinearGradient(ringW * 0.1, ringH, ringW * 0.9, 0);
      diag.addColorStop(0, 'rgba(120,220,200,0)');
      diag.addColorStop(0.42, 'rgba(120,220,200,.10)');
      diag.addColorStop(0.58, 'rgba(240,166,198,.09)');
      diag.addColorStop(1, 'rgba(240,166,198,0)');
      x.fillStyle = diag;
      x.beginPath();
      x.moveTo(0, ringH); x.lineTo(ringW * 0.62, 0); x.lineTo(ringW, 0); x.lineTo(ringW, ringH);
      x.closePath(); x.fill();
      x.restore();
      // 长流光：参考图里最抓眼的是「整片向右拉出的白色长条」，
      // 只靠每行一条细线不够，这里再补几十条长短不一的高光带（越靠右越密）。
      for (var li = 0; li < 54; li += 1) {
        var ly = ringRnd(li * 2.7) * ringH;
        var lx0 = ringW * (0.12 + ringRnd(li * 4.1) * 0.5);
        var llen = ringW * (0.1 + Math.pow(ringRnd(li * 6.3), 1.6) * 0.45);
        var la = 0.05 + Math.pow(ringRnd(li * 8.9), 2) * 0.42;
        var lg = x.createLinearGradient(lx0, ly, lx0 + llen, ly);
        lg.addColorStop(0, 'rgba(238,244,255,0)');
        lg.addColorStop(0.35, 'rgba(238,244,255,' + (la * 0.85).toFixed(3) + ')');
        lg.addColorStop(1, 'rgba(238,244,255,0)');
        x.strokeStyle = lg;
        x.lineWidth = 0.8 + ringRnd(li * 9.7) * 2.6;
        x.beginPath(); x.moveTo(lx0, ly); x.lineTo(lx0 + llen, ly); x.stroke();
      }
      // 两团光晕：冷青在左下、暖粉在右上，给整页一点「有光源」的暗示
      var glowA = x.createRadialGradient(ringW * 0.18, ringH * 1.02, 0, ringW * 0.18, ringH * 1.02, ringH * 0.9);
      glowA.addColorStop(0, 'rgba(96,196,178,.22)');
      glowA.addColorStop(1, 'rgba(96,196,178,0)');
      x.fillStyle = glowA;
      x.fillRect(0, 0, ringW, ringH);
      var glowB = x.createRadialGradient(ringW * 0.88, ringH * 0.12, 0, ringW * 0.88, ringH * 0.12, ringH * 0.75);
      glowB.addColorStop(0, 'rgba(240,166,198,.16)');
      glowB.addColorStop(1, 'rgba(240,166,198,0)');
      x.fillStyle = glowB;
      x.fillRect(0, 0, ringW, ringH);
      x.restore();
    }

    // 尺寸取「比画布还高」：环带上下都被裁掉，只留一条斜着穿过去的厚带（参考里就是这个构图）
    // 全屏时环带要「穿过整页」：半径更大、带宽更厚，弧线才会从左上斜切到右下，
    // 而不是挤在页面左侧一条窄带里（用户要的就是整页都是这张图）。
    var cx = ringW * (ringFull ? 0.28 : 0.30);
    var cy = ringH * (ringFull ? 0.52 : 0.5);
    var outer = Math.max(ringH * (ringFull ? 1.12 : 1.15), ringW * (ringFull ? 0.24 : 0.22));
    var band = Math.max(40, ringH * (ringFull ? 0.50 : 0.62));

    // 左侧网线：一堆低透明度的二次曲线，等距铺满左半边（HALOFLUX 的「研究网络」那层）
    x.save();
    x.beginPath();
    x.rect(0, 0, cx, ringH);
    x.clip();
    for (var i = 0; i < 340; i += 1) {
      var a1 = ringRnd(i * 3.1) * Math.PI * 2;
      var a2 = a1 + 0.6 + ringRnd(i * 5.7) * 3.4;
      var r1 = ringRnd(i * 1.3) * cx * 0.95;
      var r2 = ringRnd(i * 7.9) * cx * 0.95;
      var p0 = { x: cx * 0.5 + Math.cos(a1) * r1, y: cy + Math.sin(a1) * r1 * 0.9 };
      var p1 = { x: cx * 0.5 + Math.cos(a2) * r2, y: cy + Math.sin(a2) * r2 * 0.9 };
      var k = ringRnd(i * 11.3);
      var alpha = 0.05 + Math.pow(ringRnd(i * 2.2), 3) * 0.40;
      x.strokeStyle = k < 0.05 ? 'rgba(240,166,198,' + alpha.toFixed(3) + ')'
        : k < 0.1 ? 'rgba(180,170,235,' + alpha.toFixed(3) + ')'
          : 'rgba(228,231,238,' + alpha.toFixed(3) + ')';
      x.lineWidth = 0.4 + ringRnd(i * 4.4) * 0.7;
      x.beginPath();
      x.moveTo(p0.x, p0.y);
      x.quadraticCurveTo(cx * 0.5 + (ringRnd(i) - 0.5) * cx, cy + (ringRnd(i * 9.1) - 0.5) * ringH, p1.x, p1.y);
      x.stroke();
    }
    x.restore();

    // 环带本体：先在正面坐标系里画一个竖直圆环带，最后整体旋转压扁
    x.save();
    x.translate(cx, cy);
    x.rotate(RING_TILT);
    x.scale(1, RING_SQUASH / 0.46);
    var inner = outer - band;
    var grad = x.createRadialGradient(0, 0, inner, 0, 0, outer);
    grad.addColorStop(0, 'rgba(6,7,9,0)');
    grad.addColorStop(0.04, 'rgba(8,9,11,.96)');
    grad.addColorStop(0.9, 'rgba(8,9,11,.98)');
    grad.addColorStop(1, 'rgba(30,32,38,.55)');
    x.beginPath();
    x.arc(0, 0, outer, 0, Math.PI * 2);
    x.arc(0, 0, inner, 0, Math.PI * 2, true);
    x.fillStyle = grad;
    x.fill();

    // 环带里的「数据块」：沿弧长铺一格格小方阵，像一圈贴满代码的胶片
    x.save();
    x.beginPath();
    x.arc(0, 0, outer, 0, Math.PI * 2);
    x.arc(0, 0, inner, 0, Math.PI * 2, true);
    x.clip();
    var mid = (outer + inner) / 2;
    var blocks = ringFull ? 260 : 150;
    for (var b = 0; b < blocks; b += 1) {
      var ang = (b / blocks) * Math.PI * 2;
      var bw = (Math.PI * 2 / blocks) * mid * (0.35 + ringRnd(b * 3.7) * 0.6);
      var bh = band * (0.25 + ringRnd(b * 8.3) * 0.7);
      var rr = inner + (band - bh) * ringRnd(b * 5.1);
      var tint = ringRnd(b * 2.9);
      var lum = (ringFull ? 0.30 : 0.18) + ringRnd(b * 6.6) * (ringFull ? 0.62 : 0.55);
      x.save();
      x.rotate(ang);
      x.fillStyle = tint < 0.06 ? 'rgba(240,166,198,' + (lum * 0.9).toFixed(2) + ')'
        : tint < 0.16 ? 'rgba(152,224,207,' + (lum * 0.8).toFixed(2) + ')'
          : 'rgba(232,234,240,' + lum.toFixed(2) + ')';
      x.fillRect(-bw / 2, rr, bw, Math.max(1.2, bh * 0.16));
      // 块内几道细横线，远看像缩小的文字行
      for (var l = 0; l < 3; l += 1) {
        x.globalAlpha = 0.35;
        x.fillRect(-bw / 2, rr + l * 2.4 + 1.6, bw * (0.4 + ringRnd(b * 13 + l) * 0.55), 0.6);
        x.globalAlpha = 1;
      }
      x.restore();
    }
    x.restore();
    // 内外缘的两道亮线要画在裁剪之外：夹在 clip 里会被自己裁掉（第一版就是这么消失的）
    x.strokeStyle = 'rgba(240,242,248,.62)';
    x.lineWidth = 1.2;
    x.beginPath(); x.arc(0, 0, outer - 0.6, 0, Math.PI * 2); x.stroke();
    x.strokeStyle = 'rgba(240,242,248,.34)';
    x.lineWidth = 1;
    x.beginPath(); x.arc(0, 0, inner + 0.6, 0, Math.PI * 2); x.stroke();
    x.restore();

    // 右侧光带：一排近似平行的横向流线（HALOFLUX 里「光束向外扫」那层）。
    // 静态的铺在底上，动态的高光在 ringDrawFrame 里沿它们往右跑。
    ringStrands = [];
    var rimX = cx + outer * (ringFull ? 0.42 : 0.60);
    var strandCount = ringFull ? 320 : 150;
    for (var s2 = 0; s2 < strandCount; s2 += 1) {
      var sy = (s2 / (strandCount - 1)) * ringH + (ringRnd(s2 * 3.3) - 0.5) * 8;
      var sx = rimX + ringRnd(s2 * 5.9) * ringW * (ringFull ? 0.16 : 0.10);
      var sl = ringW * (0.10 + Math.pow(ringRnd(s2 * 7.7), 2) * (ringFull ? 0.9 : 0.55));
      var sa = 0.05 + Math.pow(ringRnd(s2 * 2.1), 2) * (ringFull ? 0.92 : 0.5);
      var sw = ringRnd(s2 * 9.4) < 0.12 ? 1.6 : 0.6 + ringRnd(s2 * 4.7) * 0.6;
      var grd = x.createLinearGradient(sx, sy, sx + sl, sy);
      grd.addColorStop(0, 'rgba(240,244,252,0)');
      grd.addColorStop(0.12, 'rgba(240,244,252,' + sa.toFixed(3) + ')');
      grd.addColorStop(0.55, 'rgba(226,232,244,' + (sa * 0.5).toFixed(3) + ')');
      grd.addColorStop(1, 'rgba(220,226,240,0)');
      x.strokeStyle = grd;
      x.lineWidth = sw;
      x.beginPath();
      x.moveTo(sx, sy);
      x.lineTo(sx + sl, sy + (ringRnd(s2 * 6.1) - 0.5) * 2);
      x.stroke();
      if (ringRnd(s2 * 1.7) > 0.72) {
        ringStrands.push({ y: sy, x: sx, len: sl, sp: 140 + ringRnd(s2 * 8.8) * 420, t: ringRnd(s2) * sl, w: sw });
      }
    }
    return c;
  }

  function ringSpawnBeam(now) {
    var cx = ringW * 0.30;
    var cy = ringH * 0.5;
    var outer = Math.max(ringH * 1.15, ringW * 0.22);
    // 光束从环带右半侧的内缘往外扫；角度集中在 -40°~+40°，和环带切线方向一致
    var ang = (Math.random() - 0.5) * 1.5;
    ringBeams.push({
      a: ang,
      r: outer * (0.88 + Math.random() * 0.1),
      len: ringH * (1.2 + Math.random() * 2.6),
      w: 0.6 + Math.random() * 1.8,
      sp: 60 + Math.random() * 220,
      life: 0.5 + Math.random() * 0.8,
      age: 0,
      pink: Math.random() < 0.12
    });
    // 光束是「一束」不是「一根」：同角度再补两根细的，看起来像成组飞出去
    for (var i = 0; i < 2; i += 1) {
      ringBeams.push({
        a: ang + (Math.random() - 0.5) * 0.06,
        r: outer * (0.9 + Math.random() * 0.08),
        len: ringH * (0.3 + Math.random() * 0.9),
        w: 0.4 + Math.random() * 0.8,
        sp: 90 + Math.random() * 260,
        life: 0.35 + Math.random() * 0.5,
        age: 0,
        pink: false
      });
    }
    if (ringBeams.length > 140) ringBeams.splice(0, ringBeams.length - 140);
    ringBeat = now;
  }

  function ringDrawFrame(now) {
    var x = ringCtx;
    if (!x) return;
    var dt = Math.min(0.05, (now - ringLast) / 1000);
    ringLast = now;
    if (!ringStill) ringStill = ringBuildStill();

    x.setTransform(ringDpr, 0, 0, ringDpr, 0, 0);
    x.clearRect(0, 0, ringW, ringH);
    // 静态层：极慢地左右漂一点点，像镜头在呼吸（不超过 6px，避免看久了晕）
    var drift = Math.sin(now / 5200) * 6;
    x.drawImage(ringStill, drift - 6, 0, ringW + 12, ringH);

    var cx = ringW * 0.30 + drift * 0.4;
    var cy = ringH * 0.5;
    var outer = Math.max(ringH * 1.15, ringW * 0.22);

    if (now - ringBeat > RING_BEAT_MS) ringSpawnBeam(now);

    x.globalCompositeOperation = 'lighter';
    for (var i = ringBeams.length - 1; i >= 0; i -= 1) {
      var bm = ringBeams[i];
      bm.age += dt;
      bm.r += bm.sp * dt;
      if (bm.age > bm.life) { ringBeams.splice(i, 1); continue; }
      var t = bm.age / bm.life;
      var alpha = Math.sin(Math.PI * Math.min(1, t)) * 1.5;
      var a0 = bm.a - 0.04;
      var a1 = bm.a + 0.04;
      var r0 = bm.r;
      var r1 = bm.r + bm.len;
      var g = x.createLinearGradient(cx + Math.cos(bm.a) * r0, cy + Math.sin(bm.a) * r0, cx + Math.cos(bm.a) * r1, cy + Math.sin(bm.a) * r1);
      g.addColorStop(0, bm.pink ? 'rgba(240,166,198,0)' : 'rgba(232,234,240,0)');
      g.addColorStop(0.35, bm.pink ? 'rgba(240,166,198,' + (alpha * 0.7).toFixed(3) + ')' : 'rgba(232,234,240,' + (alpha * 0.75).toFixed(3) + ')');
      g.addColorStop(1, bm.pink ? 'rgba(240,166,198,0)' : 'rgba(240,244,252,0)');
      x.strokeStyle = g;
      x.lineWidth = bm.w;
      x.beginPath();
      x.moveTo(cx + Math.cos(a0) * r0, cy + Math.sin(a0) * r0);
      x.lineTo(cx + Math.cos(a1) * r1, cy + Math.sin(a1) * r1);
      x.stroke();
    }
    // 沿流线往右跑的高光：让右侧那排线「活」起来，但比光束克制（每帧只有十几条）
    x.globalAlpha = 1;
    x.lineCap = 'round';
    for (var sj = 0; sj < ringStrands.length; sj += 1) {
      var st = ringStrands[sj];
      st.t += st.sp * dt;
      if (st.t > st.len) st.t = 0;
      var hx = st.x + st.t;
      var hl = Math.min(st.len - st.t, 26 + st.w * 30);
      if (hl <= 2) continue;
      var hg = x.createLinearGradient(hx, st.y, hx + hl, st.y);
      hg.addColorStop(0, 'rgba(255,255,255,0)');
      hg.addColorStop(0.6, 'rgba(246,250,255,' + (0.55 + (sj % 5) * 0.07).toFixed(2) + ')');
      hg.addColorStop(1, 'rgba(255,255,255,0)');
      x.strokeStyle = hg;
      x.lineWidth = st.w;
      x.beginPath(); x.moveTo(hx, st.y); x.lineTo(hx + hl, st.y); x.stroke();
    }
    x.globalCompositeOperation = 'source-over';

    // 扫描线 + 暗角：这两层是「屏幕感」的关键，缺了就像普通插画
    x.globalAlpha = 0.05;
    x.fillStyle = '#000';
    for (var y = 0; y < ringH; y += 3) x.fillRect(0, y, ringW, 1);
    x.globalAlpha = 1;
    var vg = x.createRadialGradient(cx, cy, Math.min(ringW, ringH) * 0.25, cx, cy, Math.max(ringW, ringH) * 0.85);
    vg.addColorStop(0, 'rgba(0,0,0,0)');
    vg.addColorStop(0.7, 'rgba(0,0,0,.25)');
    vg.addColorStop(1, 'rgba(0,0,0,.72)');
    x.fillStyle = vg;
    x.fillRect(0, 0, ringW, ringH);
  }

  function ringResize() {
    if (!ringCv) return;
    var rect = ringCv.getBoundingClientRect();
    ringDpr = Math.min(RING_DPR_CAP, window.devicePixelRatio || 1);
    if (rect.width < 8 || rect.height < 8) return;   // 页面被切走时是 0，别拿 0 去写画布
    ringW = Math.round(rect.width);
    ringH = Math.round(rect.height);
    ringFull = Boolean(ringHero && ringHero.classList && ringHero.classList.contains('qdb-hero-bg'));
    ringCv.width = Math.round(ringW * ringDpr);
    ringCv.height = Math.round(ringH * ringDpr);
    ringCtx = ringCv.getContext('2d');
    ringStill = null;
    ringBeams = [];
    ringLast = 0;
    ringBeat = 0;
  }

  function ringStop() {
    if (ringRaf) { window.cancelAnimationFrame(ringRaf); ringRaf = 0; }
    if (ringTimer) { window.clearInterval(ringTimer); ringTimer = 0; }
  }

  function ringTick(now) {
    ringRaf = 0;
    if (!ringSkinOn) return;
    ringDrawFrame(now || performance.now());
    if (document.hidden) return;
    ringRaf = window.requestAnimationFrame(ringTick);
  }

  function ringStart() {
    ringStop();
    if (!ringCv || !ringCtx) return;
    ringDrawFrame(performance.now());   // 先给一张静帧，避免第一帧空着
    if (ringReduced()) return;          // 减少动态：只留静帧
    ringRaf = window.requestAnimationFrame(ringTick);
  }

  // 注意顺序：监听要在「这套皮肤没开」的提前 return 之前挂上，
  // 否则第一次进来是别的皮肤就再也不会有观察者，之后切到 HUD 永远不显示。
  function ringMount() {
    if (ringMounted) return;
    ringMounted = true;
    // 仪表盘在别的页时是 display:none，量出来的宽高是 0；切回仪表盘时盒子突然有尺寸，
    // ResizeObserver 能接住这一次变化 —— 没有它，画布会永远停在 1x1（看着就是一块黑）。
    if (typeof window.ResizeObserver === 'function' && ringHero) {
      new ResizeObserver(function () {
        if (!ringSkinOn) return;
        var r = ringHero.getBoundingClientRect();
        if (r.width < 8 || r.height < 8) return;
        ringResize();
        ringStart();
      }).observe(ringHero);
    }
    window.addEventListener('resize', function () { ringResize(); ringStart(); }, { passive: true });
    document.addEventListener('visibilitychange', function () {
      if (document.hidden) ringStop();
      else if (ringSkinOn) ringStart();
    });
      // 皮肤在设置页里随时会换：盯着 data-skin，切过来就起、切走就停
    if (window.MutationObserver) {
      new MutationObserver(function () { ringSync(); }).observe(document.documentElement, { attributes: true, attributeFilter: ['data-skin'] });
    }
  }

  function ringSync() {
    var hero = document.getElementById('qdbHero');
    ringCv = document.getElementById('qdbRing');
    if (!hero || !ringCv) return;
    ringHero = hero;
    ringMount();
    ringSkinOn = document.documentElement.dataset.skin === 'halo';
    hero.hidden = !ringSkinOn;
    // 这套皮肤要的是「整页都在那张图里」：把环带画布搬成 body 级的全屏背景层。
    // 留在仪表盘 section 里的话，切到别的页签 section 被 display:none，背景就跟着没了。
    if (ringSkinOn && hero.parentNode !== document.body) {
      hero.classList.add('qdb-hero-bg');
      document.body.appendChild(hero);
    } else if (!ringSkinOn) {
      hero.classList.remove('qdb-hero-bg');
    }
    if (!ringSkinOn) { ringStop(); return; }
    ringResize();
    ringStart();
  }

  // 片段是 defer 加载的，正常情况下 DOM 已经在了；真遇到还是 loading 就等一步。
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', ringSync);
  else ringSync();
  // ── 素材库 Pro（三栏：左筛选树 / sticky 工具条 / 宽卡网格）────────────────────────
  // 与「文件库」共用同一份数据与写操作：这里只管浏览体验（筛选、搜索、密度、收藏）。
  // 后端 facets / favorite 可能还没上线：facets 404 时按同一套规则本地算，收藏 404 时给一句人话。
  var LIBPRO_PAGE = 24;
  var LIBPRO_DENSITY_KEY = 'qdb-libpro-density';
  var LIBPRO_CATEGORIES = ['饰品', '服装', '发型', '模型', '贴图', '地图', '特效', '工具', '音声', '其它', '未分类'];
  var LIBPRO_CATEGORY_RULES = [
    ['饰品', /アクセサリ|アクセ|饰品|accessor/i],
    ['服装', /衣装|コスチューム|服装|outfit|cloth/i],
    ['发型', /髪型|ヘア|发型|hair/i],
    ['模型', /モデル|model|アバター|avatar/i],
    ['贴图', /テクスチャ|texture|texture|マテリアル|material/i],
    ['地图', /ワールド|world|map|地图/i],
    ['特效', /エフェクト|effect|シェーダ|shader/i],
    ['工具', /ツール|tool|スクリプト|script/i],
    ['音声', /ボイス|voice|音声|サウンド|sound/i]
  ];
  var libProState = {
    q: '', scope: 'all', category: '', shop: '', source: '', tag: '',
    seg: 'all', quality: '', model: '', sort: 'recent',
    density: 2, items: [], shown: LIBPRO_PAGE, loading: false,
    total: 0, all: [], facets: null, facetsLocal: false, err: '',
    open: { view: true, category: true, shop: true, source: false, tag: true },
    favBusy: {}, asyncSeq: 0, purchases: null, purchasesLoaded: false,
    view: 'all', cloud: null, cloudErr: '', cloudUnsupported: false,
    serverCounts: null, serverTotals: null, cloudTotal: 0, cloudShown: 0,
    covers: { running: false, done: 0, total: 0, mode: '', timer: 0, note: '' },
    dl: { running: 0, summary: null, timer: 0, lastDone: 0 }
  };
  // v2：素材库左栏第一组 = 视图（对应后端 GET /api/library/assets?view=）
  var LIBPRO_VIEWS = [
    ['all', '全部素材', ''],
    ['with-booth', '已认号', ''],
    ['no-booth', '未认号', ''],
    ['with-cover', '有封面', ''],
    ['no-cover', '无封面', ''],
    ['suggested', '待确认建议', ''],
    ['cloud', '已购未下载', ''],
    ['favorite', '收藏', ''],
    ['trash', '回收站', ''],
    ['duplicated', '重复素材', ''],
    ['extracted', '解压产物', '']
  ];
  var libProBound = false;

  function libProDensity() {
    var n = Number(libProState.density);
    return n === 1 || n === 3 ? n : 2;
  }
  function libProDensityLoad() {
    try {
      var v = Number(localStorage.getItem(LIBPRO_DENSITY_KEY));
      if (v === 1 || v === 2 || v === 3) libProState.density = v;
    } catch (error) { /* 隐私模式：用默认中档 */ }
  }
  function libProDensitySave(n) {
    libProState.density = n === 1 || n === 3 ? n : 2;
    try { localStorage.setItem(LIBPRO_DENSITY_KEY, String(libProState.density)); } catch (error) { /* 只影响记住偏好 */ }
  }

  // 分类规则：先认后端给的规范分类，再按名字/标签关键词，最后「未分类」。与后端 §2.3 同一套词表。
  function libProLocalCategory(a) {
    if (!a) return '未分类';
    if (a.category && LIBPRO_CATEGORIES.indexOf(String(a.category)) >= 0 && a.category !== '未分类') return String(a.category);
    var meta = a.meta || {};
    if (meta.category && LIBPRO_CATEGORIES.indexOf(String(meta.category)) >= 0 && meta.category !== '未分类') return String(meta.category);
    var hay = [a.title, a.aliasTitle, a.mainName, (a.tags || []).join(' '), (meta.tags || []).join(' ')].filter(Boolean).join(' ');
    for (var i = 0; i < LIBPRO_CATEGORY_RULES.length; i++) if (LIBPRO_CATEGORY_RULES[i][1].test(hay)) return LIBPRO_CATEGORY_RULES[i][0];
    return '未分类';
  }
  function libProModelCount(a) {
    if (!a) return null;
    if (Number.isFinite(Number(a.modelCount)) && Number(a.modelCount) > 0) return Number(a.modelCount);
    var meta = a.meta || {};
    if (Array.isArray(meta.models)) return meta.models.length || null;
    if (Number.isFinite(Number(meta.models)) && Number(meta.models) > 0) return Number(meta.models);
    var m = /(\d+)\s*(?:アバター|avatars?|人対応|人)/i.exec(String(a.title || '') + ' ' + String(a.mainName || ''));
    if (m) return Number(m[1]);
    return null;
  }
  function libProModelBucket(n) {
    if (n == null || !(n > 0)) return 'unlabeled';
    if (n === 1) return '1';
    if (n <= 3) return '2-3';
    if (n <= 7) return '4-7';
    return '8+';
  }
  var LIBPRO_MODEL_LABELS = { unlabeled: '未标注', '1': '1 个', '2-3': '2~3 个', '4-7': '4~7 个', '8+': '8 个以上' };
  function libProSourceText(a) {
    var raw = String((a && (a.sourceText || a.source)) || '').trim();
    if (!raw || raw === '未知' || raw === 'unknown') return '未填来源';
    return raw;
  }
  function libProExtOf(a) {
    var m = /\.([A-Za-z0-9]{1,6})$/.exec(String((a && a.mainName) || ''));
    return m ? m[1].toUpperCase() : (a && a.kind === 'image' ? '图片' : '—');
  }
  function libProShopOf(a) {
    var meta = (a && a.meta) || {};
    return String(meta.shop || '').trim();
  }
  function libProTagsOf(a) {
    var meta = (a && a.meta) || {};
    return ([]).concat(a && a.tags ? a.tags : [], meta.tags || []).filter(Boolean);
  }
  function libProIsImage(a) {
    if (!a) return false;
    if (a.kind === 'image') return true;
    return /\.(png|jpe?g|webp|gif)$/i.test(String(a.mainName || ''));
  }

  // 标题优先级：别名 → meta.title（不是纯号）→ title；最终仍是纯号/下划线串时，卡片再补一行「原名 <主包名去扩展名>」。
  var LIBPRO_PLAIN_NAME_RE = /^[\d_\-\s.]+$/;
  function libProTitleOf(a) {
    var meta = (a && a.meta) || {};
    var alias = String((a && a.aliasTitle) || '').trim();
    if (alias) return alias;
    var metaTitle = String(meta.title || '').trim();
    if (metaTitle && !LIBPRO_PLAIN_NAME_RE.test(metaTitle)) return metaTitle;
    var t = String((a && a.title) || '').trim();
    if (t) return t;
    var n = String((a && a.mainName) || '').replace(/\.[A-Za-z0-9]{1,6}$/, '').trim();
    return n || '未命名';
  }
  function libProOrigName(a) {
    var n = String((a && a.mainName) || '').replace(/\.[A-Za-z0-9]{1,6}$/, '').trim();
    if (!n) return '';
    return n.length > 40 ? n.slice(0, 39) + '…' : n;
  }
  // 已购 = 台账对上的件数；台账拿不到返回 null（左栏「BOOTH 已购」就不显示数字，不拿「有号」冒充）。
  function libProPurchasedMap(d) {
    var map = {};
    var items = (d && (d.items || d.purchases)) || [];
    (items || []).forEach(function (it) {
      var id = String((it && (it.boothId || it.id)) || '').trim();
      if (id) map[id] = true;
    });
    return map;
  }
  function libProPurchasedCountOf(list) {
    if (!libProState.purchases) return null;
    var n = 0;
    (list || []).forEach(function (a) { if (a && a.boothId && libProState.purchases[String(a.boothId)]) n += 1; });
    return n;
  }
  function libProLoadPurchases() {
    return api('/api/library/purchases?limit=200')
      .then(function (d) {
        if (d && d.ok === false) throw new Error(String(d.error || 'purchases unavailable'));
        libProState.purchases = libProPurchasedMap(d);
        libProState.purchasesLoaded = true;
      })
      .catch(function () {
        libProState.purchases = null;
        libProState.purchasesLoaded = true;
      });
  }

  // 把一批素材按 facets 口径计数（本地兜底）。
  function libProLocalFacets(list) {
    var cat = {}, shop = {}, src = {}, tag = {}, model = {}, quality = {};
    (list || []).forEach(function (a) {
      var c = libProLocalCategory(a);
      cat[c] = (cat[c] || 0) + 1;
      var s = libProShopOf(a);
      if (s) shop[s] = (shop[s] || 0) + 1;
      var t = libProSourceText(a);
      src[t] = (src[t] || 0) + 1;
      libProTagsOf(a).forEach(function (x) { tag[x] = (tag[x] || 0) + 1; });
      var b = libProModelBucket(libProModelCount(a));
      model[b] = (model[b] || 0) + 1;
      if (!a.boothId) quality.noBooth = (quality.noBooth || 0) + 1;
      if (!a.thumbUrl && !a.coverUrl) quality.noCover = (quality.noCover || 0) + 1;
      if (c === '未分类') quality.unclassified = (quality.unclassified || 0) + 1;
      if (a.archivePassword) quality.withPassword = (quality.withPassword || 0) + 1;
      if (a.rjCode) quality.rj = (quality.rj || 0) + 1;
    });
    var toList = function (obj, labels) {
      return Object.keys(obj).sort(function (x, y) { return obj[y] - obj[x]; }).map(function (k) {
        return { value: k, label: (labels && labels[k]) || k, count: obj[k] };
      });
    };
    return {
      total: (list || []).length,
      category: toList(cat),
      shop: toList(shop),
      source: toList(src),
      tag: toList(tag),
      modelCount: toList(model, LIBPRO_MODEL_LABELS),
      quality: toList(quality, { noBooth: '未认号', noCover: '无封面', unclassified: '未分类', withPassword: '有解压码', rj: '有 RJ' }),
      purchased: libProPurchasedCountOf(list),
      free: 0
    };
  }

  // 视图口径：后端 ?view= 没上线时按同一套语义本地筛（cloud / trash 走各自的接口，不在这里判）。
  function libProHasCover(a) {
    return Boolean(a && (a.thumbUrl || a.coverUrl || a.thumbRel || a.hasCover === true));
  }
  function libProMatchView(a) {
    var v = libProState.view;
    if (v === 'with-booth') return Boolean(a && a.boothId);
    if (v === 'no-booth') return !(a && a.boothId);
    if (v === 'with-cover') return libProHasCover(a);
    if (v === 'no-cover') return !libProHasCover(a);
    if (v === 'suggested') return Boolean(a && ((Array.isArray(a.bindSuggestions) && a.bindSuggestions.length > 0) || a.suggestion || a.suggestedBoothId || (a.suggested && a.suggested.boothId) || a.suggestedTitle));
    if (v === 'favorite') return Boolean(a && a.favorite === true);
    return libDupMatch(a, v);
  }
  // 本地筛选（服务端参数没上线时也保证页面能用）。
  function libProMatch(a) {
    if (libProState.view !== 'cloud' && libProState.view !== 'trash' && !libProMatchView(a)) return false;
    if (libProState.scope === 'purchased') {
      if (!a.boothId) return false;
      if (libProState.purchases && !libProState.purchases[String(a.boothId)]) return false;
    }
    if (libProState.scope === 'free') return false; // 没有免费台账：本地兜底一律不算免费
    if (libProState.scope === 'noid' && a.boothId) return false;
    if (libProState.category && libProLocalCategory(a) !== libProState.category) return false;
    if (libProState.shop && libProShopOf(a) !== libProState.shop) return false;
    if (libProState.source && libProSourceText(a) !== libProState.source) return false;
    if (libProState.tag && libProTagsOf(a).indexOf(libProState.tag) < 0) return false;
    if (libProState.model && libProModelBucket(libProModelCount(a)) !== libProState.model) return false;
    if (libProState.seg === 'image' && !libProIsImage(a)) return false;
    if (libProState.seg === 'fav' && a.favorite !== true) return false;
    if (libProState.quality === 'unclassified' && libProLocalCategory(a) !== '未分类') return false;
    if (libProState.quality === 'noCover' && (a.thumbUrl || a.coverUrl)) return false;
    if (libProState.quality === 'noBooth' && a.boothId) return false;
    if (libProState.quality === 'withPassword' && !a.archivePassword) return false;
    if (libProState.quality === 'rj' && !a.rjCode) return false;
    if (libProState.quality === 'extracted') {
      var exL = a.extracted;
      var exNL = exL ? Number(exL.count || (Array.isArray(exL.files) ? exL.files.length : 0) || 0) : Number(a.extractedCount || 0);
      if (!exNL) return false;
    }
    if (libProState.quality === 'duplicated') {
      if (a.duplicated === true) return true;
      if (Array.isArray(a.duplicateGroup) || Array.isArray(a.dupMembers)) return true;
      var same = libProState.all.filter(function (x) { return x.boothId && a.boothId && x.boothId === a.boothId; });
      if (same.length < 2) return false;
    }
    return true;
  }
  function libProVisible() {
    return (libProState.all || []).filter(libProMatch).filter(function (a) { return libProColKeep(a); });
  }
  function libProShown() { return libProVisible().slice(0, libProState.shown); }

  function libProCount(list) { return Array.isArray(list) ? list.length : 0; }
  function libProFacetsList(key) {
    var f = libProState.facets || libProLocalFacets(libProState.all);
    return Array.isArray(f[key]) ? f[key] : [];
  }

  // ── 渲染：页面骨架只建一次，之后局部重画 ───────────────────────────────
  function pageLibraryPro(view, host) {
    if (!libProBound) { libProBind(); libProBound = true; }
    if (typeof libProMainBind === 'function') libProMainBind();
    libProDensityLoad();
    host.innerHTML = '<div class="qdb-libpro" data-density="' + libProDensity() + '">'
      + '<aside class="qdb-libpro-side" id="libProSide"></aside>'
      + '<div class="qdb-libpro-main">'
      + '<div class="qdb-libpro-bar">'
      + '<button class="qdb-btn qdb-btn-mini qdb-libpro-side-toggle" type="button" id="libProSideToggle" aria-expanded="false" title="窄屏时收起/展开筛选栏">筛选</button>'
      + '<input class="qdb-input qdb-libpro-search" type="search" id="libProSearch" value="' + esc(libProState.q)
      + '" placeholder="搜索素材名、标签、店铺、模型或 BOOTH 商品（Ctrl+K）" aria-label="搜索素材">'
      + '<button class="qdb-btn qdb-btn-mini" type="button" id="libProSearchClear" title="清空搜索">✕</button>'
      + '<select class="qdb-select qdb-libpro-select" id="libProModel" aria-label="适配模型">' + libProModelOptions() + '</select>'
      + '<span class="qdb-seg qdb-libpro-seg" role="group" aria-label="素材范围">'
      + libProSegButton('all', '全部') + libProSegButton('image', '仅图片') + libProSegButton('fav', '收藏') + '</span>'
      + '<select class="qdb-select qdb-libpro-select" id="libProQuality" aria-label="质量检查">' + libProQualityOptions() + '</select>'
      + '<select class="qdb-select qdb-libpro-select" id="libProSort" aria-label="排序">' + libProSortOptions() + '</select>'
      + '<span class="qdb-libpro-syncslot" id="libProSyncSlot"></span>'
      + '<label class="qdb-libpro-density" title="卡片密度（大 / 中 / 小）">▦'
      + '<input type="range" id="libProDensity" min="1" max="3" step="1" value="' + libProDensity() + '" aria-label="卡片密度">'
      + '</label>' + libProTopExtraHtml()
      + '</div>'
      + '<div class="qdb-libpro-tools" id="libProTools"></div>'
      + '<div class="qdb-libpro-cats" id="libProCats"></div>'
      + '<div id="libProBatch"></div>'
      + '<div id="libProBatchExtra"></div>'
      + '<div class="qdb-libpro-grid" id="libProGrid"></div>'
      + '<div class="qdb-libpro-foot" id="libProFoot"></div>'
      + '</div></div>';
    if (typeof libSyncEntryMount === 'function') libSyncEntryMount();
    var bar = byId('libProBatch');
    if (bar && typeof libBatchBarHtml === 'function') bar.innerHTML = libBatchBarHtml();
    libProPaintSide();
    libProPaintTools();
    libProLoad();
    libProDlTick();
  }
  function libProSegButton(v, label) {
    return '<button class="qdb-seg-btn" type="button" data-libpro-seg="' + v + '" aria-pressed="'
      + (libProState.seg === v ? 'true' : 'false') + '">' + label + '</button>';
  }
  function libProModelOptions() {
    var opts = [['', '适配模型：全部'], ['unlabeled', '未标注'], ['1', '1 个'], ['2-3', '2~3 个'], ['4-7', '4~7 个'], ['8+', '8 个以上']];
    return opts.map(function (it) {
      return '<option value="' + it[0] + '"' + (libProState.model === it[0] ? ' selected' : '') + '>' + it[1] + '</option>';
    }).join('');
  }
  function libProQualityOptions() {
    var opts = [['', '质量检查：全部'], ['unclassified', '未分类'], ['noCover', '无封面'], ['noBooth', '未认号'],
      ['withPassword', '有解压码'], ['rj', '有 RJ'], ['extracted', '已解压（未归档）'], ['duplicated', '重复（组内）']];
    return opts.map(function (it) {
      return '<option value="' + it[0] + '"' + (libProState.quality === it[0] ? ' selected' : '') + '>' + it[1] + '</option>';
    }).join('');
  }
  function libProSortOptions() {
    var opts = [['recent', '最近导入'], ['title', '名称'], ['bytes', '大小'], ['use', '使用次数'], ['lastUsed', '最近使用']];
    return opts.map(function (it) {
      return '<option value="' + it[0] + '"' + (libProState.sort === it[0] ? ' selected' : '') + '>' + it[1] + '</option>';
    }).join('');
  }

  // 左栏：快捷组 + 四组 facet 树（可折叠、带计数、当前项高亮）
  function libProSideGroup(key, title, rows, current, attr) {
    var open = libProState.open[key] !== false;
    var head = '<button class="qdb-libpro-group-head" type="button" data-libpro-group="' + key + '" aria-expanded="' + open + '">'
      + '<span class="qdb-libpro-arrow" aria-hidden="true">' + (open ? '▾' : '▸') + '</span>' + esc(title) + '</button>';
    if (!open) return '<div class="qdb-libpro-group">' + head + '</div>';
    var body = rows.length ? rows.join('') : '<p class="qdb-hint qdb-libpro-empty-row">没有可选的</p>';
    return '<div class="qdb-libpro-group">' + head + '<div class="qdb-libpro-list">' + body + '</div></div>';
  }
  function libProSideRow(attr, value, label, count, active) {
    return '<button class="qdb-libpro-row' + (active ? ' is-active' : '') + '" type="button" ' + attr + '="' + esc(value)
      + '" aria-pressed="' + (active ? 'true' : 'false') + '">'
      + '<span class="qdb-libpro-row-label">' + esc(label) + '</span>'
      + (count == null ? '' : '<span class="qdb-libpro-count">' + numText(count) + '</span>') + '</button>';
  }
  function libProManualCatMap() {
    var map = {};
    function scan(list) {
      (list || []).forEach(function (a) {
        if (!a) return;
        var c = String(a.manualCategory || '') || (a.categoryFrom === 'manual' ? String(a.category || '') : '');
        if (c) map[c] = true;
      });
    }
    scan(libProState.items);
    scan(libProState.all);
    return map;
  }
  // 左栏/视图计数优先用服务端：counts（不全时按 withBooth/withCover/total 兜底），
  // 只有服务端完全没给数时才回退本地算，避免「左栏 5 / 服务端 31」这种自相矛盾。
  function libDupGroupCount() {
    var n = libProState.serverCounts && libProState.serverCounts.duplicateGroups;
    return isFinite(Number(n)) && Number(n) > 0 ? Number(n) : null;
  }
  function libProCountNum(v) { return v == null || v === '' || !isFinite(Number(v)) ? null : Number(v); }
  function libProServerCount(name) {
    var c = libProState.serverCounts || {};
    var t = libProState.serverTotals || {};
    var map = {
      all: [c.all, t.allCount, t.total],
      'with-booth': [c.withBooth, t.withBooth],
      'no-booth': [c.noBooth, t.noBooth],
      'with-cover': [c.withCover, t.withCover],
      'no-cover': [c.noCover],
      favorite: [c.favorite, t.favorites],
      cloud: [c.cloud],
      trash: [c.trash], duplicated: [c.duplicated, typeof libDupCount === 'function' ? libDupCount() : null]
    };
    var sgl = name === 'suggested' && typeof libProSuggestionCount === 'function' ? libProSuggestionCount() : 0;
    if (sgl > 0 && !(libProCountNum(c.suggested) > 0)) return sgl;
    var list = map[name] || [];
    for (var i = 0; i < list.length; i += 1) {
      var n = libProCountNum(list[i]);
      if (n != null) return n;
    }
    return null;
  }
  function libProPaintSide() {
    var box = byId('libProSide');
    if (!box) return;
    var f = libProState.facets || libProLocalFacets(libProState.all);
    var total = Number(f.total) || libProCount(libProState.all);
    var noBooth = libProFacetsList('quality').filter(function (q) { return q.value === 'noBooth'; }).map(function (q) { return q.count; })[0] || 0;
    var noCover = libProFacetsList('quality').filter(function (q) { return q.value === 'noCover'; }).map(function (q) { return q.count; })[0] || 0;
    var withCover = Math.max(0, total - Number(noCover || 0));
    var cloudCount = libProCloudCount(), local = {
      all: total, 'with-booth': f.purchased == null ? null : Number(f.purchased), 'no-booth': noBooth,
      'with-cover': withCover, 'no-cover': noCover, cloud: cloudCount, favorite: null, trash: null
    };
    var rows = LIBPRO_VIEWS.map(function (it) {
      var srv = libProServerCount(it[0]), count = srv != null ? srv : local[it[0]];
      var vlabel = it[1];
      var gc = libDupGroupCount(); if (it[0] === 'duplicated' && gc) vlabel += '（' + numText(gc) + ' 组）';
      return libProSideRow('data-libpro-view', it[0], vlabel, count, libProState.view === it[0]);
    }).join('');
    var quick = libProMainEntriesHtml() + '<div class="qdb-libpro-group qdb-libpro-quick">' + rows + '</div>' + libProSideExtra(); var manualCats = libProManualCatMap();
    var catRows = libProFacetsList('category').map(function (c) {
      var label = c.label || c.value;
      if (manualCats[c.value]) label += ' · 手动';
      return libProSideRow('data-libpro-category', c.value, label, c.count, libProState.category === c.value);
    });
    if (libProState.catSort === 'name') catRows.sort(function (x, y) { return x.localeCompare(y, 'zh-Hans-CN'); });
    if (!libProState.catExpanded && catRows.length > 12) catRows = catRows.slice(0, 12);
    var shopRows = libProFacetsList('shop').slice(0, 12).map(function (s) {
      return libProSideRow('data-libpro-shop', s.value, s.value, s.count, libProState.shop === s.value);
    });
    var srcRows = libProFacetsList('source').map(function (s) {
      return libProSideRow('data-libpro-source', s.value, s.label || s.value, s.count, libProState.source === s.value);
    });
    var tagRows = libProFacetsList('tag').slice(0, 16).map(function (t) {
      return libProSideRow('data-libpro-tag', t.value, t.value, t.count, libProState.tag === t.value);
    });
    box.innerHTML = quick
      + libProSideGroup('category', '分类', catRows, libProState.category, 'data-libpro-category')
      + (libProFacetsList('category').length > 12 ? '<button class="qdb-libpro-more" type="button" data-libpro-catmore="1">'
        + (libProState.catExpanded ? '收起' : '展开全部 ' + numText(libProFacetsList('category').length) + ' 个子分类') + '</button>' : '')
      + libProSideGroup('shop', '店铺', shopRows, libProState.shop, 'data-libpro-shop')
      + libProSideGroup('source', '来源', srcRows, libProState.source, 'data-libpro-source')
      + libProSideGroup('tag', '标签', tagRows, libProState.tag, 'data-libpro-tag');
  }

  function libProPaintCats() {
    var box = byId('libProCats');
    if (!box) return;
    var rows = libProFacetsList('category');
    if (!rows.length) { box.innerHTML = ''; return; }
    var pills = ['<button class="qdb-seg-btn" type="button" data-libpro-category="" aria-pressed="'
      + (libProState.category ? 'false' : 'true') + '">全部 ' + numText(libProCount(libProState.all)) + '</button>'];
    rows.forEach(function (c) {
      pills.push('<button class="qdb-seg-btn" type="button" data-libpro-category="' + esc(c.value) + '" aria-pressed="'
        + (libProState.category === c.value ? 'true' : 'false') + '">' + esc(c.label || c.value) + ' ' + numText(c.count) + '</button>');
    });
    box.innerHTML = '<span class="qdb-seg" id="libProCatSeg" role="group" aria-label="按分类筛选">' + pills.join('') + libProCatPillsExtra() + '</span>';
  }

  var LIBPRO_REJECT_KEY = 'qdb-libpro-rejected-suggestions';
  function libProPaintFoot() {
    var foot = byId('libProFoot');
    if (!foot) return;
    var total = libProIsCloud() ? (Number(libProState.cloudTotal) || libProCloudList().length) : libProFootCount();
    var shown = libProIsCloud() ? libProCloudList().length : libProShown().length;
    var footText = libProIsCloud()
      ? '已显示 ' + numText(shown) + '/' + numText(total) + ' 件'
      : '共 ' + numText(total) + ' 件 · 已显示 ' + numText(shown);
    foot.innerHTML = '<span class="qdb-batch-text">' + footText + '</span>'
      + (shown < total
        ? '<button class="qdb-btn qdb-btn-mini" type="button" id="libProMore">加载更多</button>'
        : '');
  }

  // ── 数据：facets（404 → 本地算）+ assets（一次取全，本地筛/分页）───────────
  function libProLoadFacets() {
    return api('/api/library/facets' + (libProState.q ? '?q=' + encodeURIComponent(libProState.q) : ''))
      .then(function (d) {
        if (d && d.ok !== false && d.facets) {
          libProState.facets = d.facets;
          libProState.facetsLocal = false;
        } else {
          libProState.facets = libProLocalFacets(libProState.all);
          libProState.facetsLocal = true;
        }
      })
      .catch(function () {
        libProState.facets = libProLocalFacets(libProState.all);
        libProState.facetsLocal = true;
      });
  }
  function libProLoad() {
    var seq = ++libProState.asyncSeq;
    libProState.loading = true;
    libProState.err = '';
    libProPaintGrid();
    if (libProIsCloud()) return libProLoadCloud();
    var viewQ = libProView() && libProView() !== 'all' && !libColIsView() ? '&view=' + encodeURIComponent(libProView()) : '';
    var filterQ = libProView() === 'duplicated' ? 'duplicated' : (libProState.quality === 'extracted' ? 'extracted' : 'all');
    var url = '/api/library/assets?limit=200&filter=' + filterQ + '&sort=' + encodeURIComponent(libProState.sort) + viewQ
      + (libProState.q ? '&q=' + encodeURIComponent(libProState.q) : '')
      + (libProState.category ? '&category=' + encodeURIComponent(libProState.category) : '');
    return api(url).then(function (d) {
      if (seq !== libProState.asyncSeq) return null;
      if (d && d.ok === false) {
        libProState.err = String(d.error || '素材扫描失败');
        libProState.loading = false;
        libProPaintGrid();
        return null;
      }
      var list = Array.isArray(d && d.assets) ? d.assets : (Array.isArray(d && d.items) ? d.items : []);
      libProState.all = list;
      libProState.total = Number(d && d.total) || list.length;
      libProState.serverCounts = d && d.counts && typeof d.counts === 'object' ? d.counts : null;
      libProState.serverTotals = {
        total: Number(d && d.total) || list.length,
        allCount: d && d.allCount != null ? Number(d.allCount) : null,
        withBooth: d && d.withBooth != null ? Number(d.withBooth) : null,
        withCover: d && d.withCover != null ? Number(d.withCover) : null,
        favorites: d && d.favorites != null ? Number(d.favorites) : null
      };
      libProState.shown = LIBPRO_PAGE;
      libProState.facets = libProState.facets && !libProState.facetsLocal ? libProState.facets : libProLocalFacets(list);
      libProState.loading = false;
      libProPaintSide();
      libProPaintCats();
      libProPaintGrid();
      return libProLoadFacets().then(function () {
        if (seq !== libProState.asyncSeq) return null;
        libProPaintSide();
        libProPaintCats();
        if (libProState.purchasesLoaded) return null;
        return libProLoadPurchases().then(function () {
          if (seq !== libProState.asyncSeq) return null;
          if (libProState.facetsLocal) libProState.facets = libProLocalFacets(libProState.all);
          libProPaintSide();
          libProPaintCats();
          return null;
        });
      });
    }).catch(function (error) {
      if (seq !== libProState.asyncSeq) return null;
      libProState.loading = false;
      var msg = String((error && error.message) || error || '');
      libProState.err = /HTTP 404/.test(msg) ? '后端还没上线素材库视图（接口 404）：重启桥接后再试。' : '素材读取失败：' + msg;
      libProPaintGrid();
      return null;
    });
  }

  function libProSetSeg(v) { libProState.seg = v; libProPaintBar(); libProPaintGrid(); }
  function libProSetScope(scope) {
    libProState.scope = libProState.scope === scope ? 'all' : scope;
    libProState.shown = LIBPRO_PAGE;
    libProPaintSide();
    libProPaintGrid();
  }
  function libProSetFacet(kind, value) {
    var key = kind === 'category' ? 'category' : kind;
    libProState[key] = libProState[key] === value ? '' : value;
    libProState.shown = LIBPRO_PAGE;
    // 分类筛选走服务端（assets?category=…，中文经 encodeURIComponent）：回来会重画侧栏/胶囊/网格
    if (kind === 'category') { libProPaintSide(); libProPaintCats(); libProLoad(); return; }
    libProPaintSide();
    libProPaintCats();
    libProPaintGrid();
  }
  function libProPaintBar() {
    var seg = document.querySelectorAll('[data-libpro-seg]');
    for (var i = 0; i < seg.length; i++) seg[i].setAttribute('aria-pressed', seg[i].getAttribute('data-libpro-seg') === libProState.seg ? 'true' : 'false');
  }
  function libProSetDensity(n) {
    libProDensitySave(n);
    var root = document.querySelector('.qdb-libpro');
    if (root) root.setAttribute('data-density', String(libProDensity()));
  }

  // 收藏：POST 失败（常见 404：后端还没上线）说人话并回滚。
  function libProFav(btn) {
    var key = String((btn && btn.getAttribute('data-libpro-fav')) || '');
    if (!key) return Promise.resolve(null);
    var a = null;
    libProState.all.forEach(function (x) { if (x.key === key) a = x; });
    if (!a) return Promise.resolve(null);
    var on = a.favorite !== true;
    if (libProState.favBusy[key]) return Promise.resolve(null);
    libProState.favBusy[key] = true;
    a.favorite = on;
    libProPaintGrid();
    return apiWrite('/api/library/favorite', { key: key, on: on })
      .then(function (d) {
        libProState.favBusy[key] = false;
        if (d && d.ok === false) throw new Error(String(d.error || '收藏失败'));
        toast(on ? '已收藏' : '已取消收藏', 'ok');
        libProState.facets = libProLocalFacets(libProState.all);
        libProPaintSide();
        libProPaintGrid();
        return null;
      })
      .catch(function (error) {
        libProState.favBusy[key] = false;
        a.favorite = !on;
        libProPaintGrid();
        var msg = String((error && error.message) || error || '');
        toast(/HTTP 404/.test(msg) ? '后端还没上线收藏接口（重启桥接后再试）' : '收藏失败：' + msg, /HTTP 404/.test(msg) ? 'warn' : 'err');
        return null;
      });
  }

  // ── 事件：顶栏/左栏/网格/快捷键（片段自己绑，不碰 01-shell 的 WRITE_ACTIONS）──
  function libProBind() {
    document.addEventListener('click', function (ev) {
      var t = ev.target;
      if (!t || !t.closest) return;
      var page = t.closest('[data-page="library-pro"]');
      if (!page) return;
      var seg = t.closest('[data-libpro-seg]');
      if (seg) { libProSetSeg(seg.getAttribute('data-libpro-seg')); return; }
      var vrow = t.closest('[data-libpro-view]');
      if (vrow) { libProSetView(vrow.getAttribute('data-libpro-view')); return; }
      var scope = t.closest('[data-libpro-scope]');
      if (scope) { libProSetScope(scope.getAttribute('data-libpro-scope')); return; }
      var menuBtn = t.closest('[data-toggle]');
      if (menuBtn) {
        var target = byId(menuBtn.getAttribute('data-toggle'));
        if (target) target.hidden = !target.hidden;
        return;
      }
      var coverMode = t.closest('[data-libpro-covers-mode]');
      if (coverMode) { libProCoversStart(coverMode.getAttribute('data-libpro-covers-mode')); return; }
      var coverStop = t.closest('[data-write="library-pro-covers-stop"]');
      if (coverStop) { return; }
      var group = t.closest('[data-libpro-group]');
      if (group) {
        var gk = group.getAttribute('data-libpro-group');
        libProState.open[gk] = libProState.open[gk] === false;
        libProPaintSide();
        return;
      }
      var cat = t.closest('[data-libpro-category]');
      if (cat) { libProSetFacet('category', cat.getAttribute('data-libpro-category')); return; }
      var shop = t.closest('[data-libpro-shop]');
      if (shop) { libProSetFacet('shop', shop.getAttribute('data-libpro-shop')); return; }
      var src = t.closest('[data-libpro-source]');
      if (src) { libProSetFacet('source', src.getAttribute('data-libpro-source')); return; }
      var tag = t.closest('[data-libpro-tag]');
      if (tag) { libProSetFacet('tag', tag.getAttribute('data-libpro-tag')); return; }
      var favBtn = t.closest('[data-libpro-fav]');
      if (favBtn) { libProFav(favBtn); return; }
      if (t.closest('#libProSideToggle')) {
        var side = byId('libProSide');
        var open = !(side && side.classList.contains('is-open'));
        if (side) side.classList.toggle('is-open', open);
        var toggle = byId('libProSideToggle');
        if (toggle) toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
        return;
      }
      if (t.closest('#libProSearchClear')) {
        libProState.q = '';
        var input = byId('libProSearch');
        if (input) input.value = '';
        libProState.shown = LIBPRO_PAGE;
        libProLoad();
        return;
      }
      var reject = t.closest('[data-libpro-suggest-reject]');
      if (reject) {
        libProRejectSave(String(reject.getAttribute('data-libpro-suggest-reject') || ''));
        libProPaintGrid();
        toast('好的，这条候选不再提示（只记在这台浏览器）', 'info');
        return;
      }
      if (t.closest('#libProMore')) {
        if (libProIsCloud()) { libProLoadCloud(true); return; }
        libProState.shown += LIBPRO_PAGE;
        libProPaintGrid();
        return;
      }
    });
    document.addEventListener('input', function (ev) {
      var t = ev.target;
      if (!t) return;
      if (t.id === 'libProSearch') {
        libProState.q = String(t.value || '');
        if (libProState.timer) clearTimeout(libProState.timer);
        libProState.timer = setTimeout(function () { libProLoad(); }, 300);
        return;
      }
      if (t.id === 'libProDensity') libProSetDensity(Number(t.value));
    });
    document.addEventListener('change', function (ev) {
      var t = ev.target;
      if (!t || !t.id) return;
      if (t.id === 'libProModel') { libProState.model = String(t.value || ''); libProState.shown = LIBPRO_PAGE; libProPaintGrid(); return; }
      if (t.id === 'libProQuality') { libProState.quality = String(t.value || ''); libProState.shown = LIBPRO_PAGE; libProPaintGrid(); return; }
      if (t.id === 'libProSort') { libProState.sort = String(t.value || 'recent'); libProLoad(); return; }
    });
    document.addEventListener('keydown', function (ev) {
      var card = ev.target && ev.target.closest ? ev.target.closest('.qdb-libpro-card') : null;
      if (card && (ev.key === 'Enter' || ev.key === ' ')) {
        var title = card.querySelector('.qdb-libpro-title');
        if (title) { ev.preventDefault(); title.click(); return; }
      }
      if (!(ev.ctrlKey || ev.metaKey) || String(ev.key || '').toLowerCase() !== 'k') return;
      if (!document.querySelector('[data-page="library-pro"]:not([hidden])')) return;
      var input = byId('libProSearch');
      if (!input) return;
      ev.preventDefault();
      input.focus();
      input.select();
    });
    // 滚动到底自动加载下一页（只在 Pro 页可见时生效）
    window.addEventListener('scroll', function () {
      if (!document.querySelector('[data-page="library-pro"]:not([hidden])')) return;
      var foot = byId('libProFoot');
      if (!foot || !byId('libProMore')) return;
      var rect = foot.getBoundingClientRect();
      if (rect.top > (window.innerHeight || 800) + 200) return;
      if (libProIsCloud()) { libProLoadCloud(true); return; }
      libProState.shown += LIBPRO_PAGE;
      libProPaintGrid();
    }, { passive: true });
    // 批量条附加动作（补封面 / 下载）：勾选变化时跟着重画
    if (typeof libBatchPaint === 'function' && !libProState.batchPainted) {
      var baseBatchPaint = libBatchPaint;
      libBatchPaint = function () {
        var r = baseBatchPaint.apply(null, arguments);
        try { libProPaintBatchExtra(); } catch (error) { /* 附加条不是关键路径 */ }
        return r;
      };
      libProState.batchPainted = true;
    }
    // 批量条：libBatchSelectAll 取「当前屏」的钩子（Pro 用自己的网格，不碰 07o 的函数实现）
    if (typeof libBatchOnPage === 'function') {
      var baseBatchOnPage = libBatchOnPage;
      libBatchOnPage = function () {
        if (byId('libProGrid')) return libProShown().map(function (a) { return a && a.key; }).filter(Boolean);
        return baseBatchOnPage();
      };
    }
  }

  // ══ v2 整合：视图组 / 工具条 / 已购未下载 / 下载中心 / 按名字找号 ══════════
  function libProView() { return String(libProState.view || 'all'); }
  function libProIsCloud() { return libProView() === 'cloud'; }
  function libProIsTrash() { return libProView() === 'trash'; }
  function libProCloudList() { return Array.isArray(libProState.cloud) ? libProState.cloud : []; }
  function libProCloudCount() {
    if (Array.isArray(libProState.cloud)) return libProState.cloud.length;
    var rec = libSyncEntryState && libSyncEntryState.recon;
    var stats = (rec && (rec.stats || rec)) || {};
    return Number.isFinite(Number(stats.missing)) ? Number(stats.missing) : null;
  }
  function libProSetView(v) {
    var next = String(v || 'all');
    libProState.view = libProState.view === next && next !== 'all' ? 'all' : next;
    libProState.shown = LIBPRO_PAGE;
    libProState.err = '';
    libProPaintSide();
    libProPaintTools();
    libProLoad();
  }

  function libProBatchExtraHtml() {
    if (typeof libBatchState !== 'object' || !libBatchState) return '';
    var n = (libBatchState.keys || []).length;
    if (!n) return '';
    return '<div class="qdb-batch-bar"><span class="qdb-batch-text">已选 ' + numText(n) + ' 件</span>'
      + '<button class="qdb-btn qdb-btn-mini" type="button" data-write="library-pro-batch-covers">补封面</button>'
      + (libProIsCloud() ? '<button class="qdb-btn qdb-btn-mini" type="button" data-write="library-pro-batch-download">下载</button>' : '')
      + '</div>';
  }
  function libProPaintBatchExtra() {
    var box = byId('libProBatchExtra');
    if (box) box.innerHTML = libProBatchExtraHtml();
  }
  function libProBatchCovers() {
    var keys = (libBatchState && libBatchState.keys) || [];
    if (!keys.length) { toast('先勾几件素材', 'warn'); return null; }
    return apiWrite('/api/library/covers/backfill', { keys: keys.slice(0, 200) }).then(function () {
      toast('已加入补封面队列：' + numText(keys.length) + ' 件', 'ok');
      libProCoversPoll();
      return null;
    }).catch(function (error) {
      var msg = String((error && error.message) || '');
      toast(/HTTP 404/.test(msg) ? '后端还没上线补封面（重启桥接后再试）' : '补封面失败：' + msg.replace(/^HTTP \d+ · /, ''), /404/.test(msg) ? 'warn' : 'err');
      return null;
    });
  }
  function libProBatchDownload() {
    var keys = (libBatchState && libBatchState.keys) || [];
    var ids = keys.map(function (k) { return String(k || '').replace(/^purchase:/, ''); }).filter(Boolean);
    if (!ids.length) { toast('先勾几件已购未下载的', 'warn'); return null; }
    return Promise.all(ids.slice(0, 20).map(function (id) {
      return apiWrite('/api/library/purchases/download', { boothId: id }).catch(function () { return null; });
    })).then(function () {
      toast('已加入下载队列：' + numText(ids.length) + ' 件', 'ok');
      libProDlTick();
      return null;
    });
  }

  // 卡片上的分类 chip 点一下 = 走左栏同一个分类筛选（由 01-shell 的 library-cat-jump 调进来）
  function libProCatJump(cat) {
    libProState.category = String(cat || '');
    libProState.view = libProState.view === 'cloud' ? 'cloud' : 'all';
    libProState.shown = LIBPRO_PAGE;
    libProPaintSide();
    libProPaintCats();
    libProPaintGrid();
    return true;
  }

  PAGE_LOADERS['library-pro'] = pageLibraryPro;
  PAGE_TITLES['library-pro'] = '素材库';
  // ── 素材库 · 按名字找号面板（从 10-library-pro.js 拆出，纯搬运）──────────────
  // ── 按名字找号（替代被删的找号页）────────────────────────────────────
  function libNameFindOpen() {
    if (byId('nameFindMask')) return null;
    var mask = document.createElement('div');
    mask.className = 'qdb-dialog-mask';
    mask.id = 'nameFindMask';
    var box = document.createElement('div');
    box.className = 'qdb-dialog qdb-dialog-wide';
    box.innerHTML = '<h2 class="qdb-dialog-title">按名字找号</h2>'
      + '<p class="qdb-dialog-text">一行一个名字或商品号；搜到后点「绑这个」把号写进素材。商品号可以直接粘贴。</p>'
      + '<textarea class="qdb-input qdb-textarea" id="nameFindInput" rows="4" spellcheck="false" placeholder="例如：&#10;Mew_Pose&#10;8664050"></textarea>'
      + '<div class="qdb-dialog-foot qdb-dlg-acts">'
      + '<button class="qdb-btn qdb-btn-mini" type="button" id="nameFindGo">搜索</button>'
      + '<span class="qdb-hint" id="nameFindHint"></span>'
      + '</div>'
      + '<div class="qdb-find-list" id="nameFindList"></div>'
      + '<div class="qdb-dialog-foot"><button class="qdb-btn" type="button" data-dl-close>关掉</button></div>';
    mask.appendChild(box);
    document.body.appendChild(mask);
    function close() {
      document.removeEventListener('keydown', onKey);
      if (mask.parentNode) mask.parentNode.removeChild(mask);
    }
    function onKey(ev) { if (ev.key === 'Escape') close(); }
    document.addEventListener('keydown', onKey);
    box.querySelector('[data-dl-close]').addEventListener('click', close);
    mask.addEventListener('click', function (ev) { if (ev.target === mask) close(); });
    box.querySelector('#nameFindGo').addEventListener('click', function () {
      var raw = String((box.querySelector('#nameFindInput') || {}).value || '');
      var lines = raw.split(/\r?\n/).map(function (x) { return x.trim(); }).filter(Boolean).slice(0, 10);
      var list = box.querySelector('#nameFindList');
      var hint = box.querySelector('#nameFindHint');
      if (!lines.length) { hint.textContent = '先填至少一行'; return; }
      hint.textContent = '搜索中…';
      list.innerHTML = '';
      var rows = [];
      var seq = 0;
      var jobs = lines.map(function (line) {
        return api('/api/library/assets?limit=20&q=' + encodeURIComponent(line)).then(function (d) {
          var assets = Array.isArray(d && d.assets) ? d.assets : [];
          return assets.filter(function (a) { return a && a.key; });
        }).catch(function () { return []; });
      });
      return Promise.all(jobs).then(function (groups) {
        groups.forEach(function (g, i) {
          var line = lines[i];
          if (!g.length) {
            rows.push('<p class="qdb-hint">「' + esc(line) + '」没搜到素材</p>');
            return;
          }
          rows.push('<p class="qdb-hint">「' + esc(line) + '」搜到 ' + numText(g.length) + ' 件</p>');
          g.slice(0, 10).forEach(function (a) {
            seq += 1;
            var id = a.boothId ? '#' + esc(a.boothId) : '未认号';
            rows.push('<div class="qdb-find-row" id="nameFindRow' + seq + '">'
              + '<div class="qdb-find-main"><div class="qdb-find-title">' + esc(a.title || a.mainName || a.key) + '</div>'
              + '<div class="qdb-find-meta">' + id + (a.shopName ? ' · ' + esc(a.shopName) : '') + (a.priceText ? ' · ' + esc(a.priceText) : '') + '</div></div>'
              + '<div class="qdb-find-acts">'
              + '<button class="qdb-btn qdb-btn-mini" type="button" data-write="library-bind-manual" data-key="' + esc(a.key) + '"'
              + (a.boothId ? ' data-booth="' + esc(a.boothId) + '"' : '') + (a.title ? ' data-title="' + esc(a.title) + '"' : '') + '>绑这个</button>'
              + '</div></div>');
          });
        });
        list.innerHTML = rows.join('');
        hint.textContent = '搜完 ' + numText(lines.length) + ' 行';
        return null;
      });
    });
    return null;
  }
  // ── 素材库 · 补封面 + 下载中心（从 10-library-pro.js 拆出，纯搬运）───────────
