      + '<button class="qdb-btn qdb-btn-mini" type="button" data-write="library-batchfind" title="把还没认号的素材一次搜一遍">批量找号</button>'
      + '<button class="qdb-btn qdb-btn-mini" type="button" data-write="library-batchfind-stop" title="停掉这一轮找号">停止</button>'
