      + '<button class="qdb-btn qdb-btn-mini" type="button" data-write="library-alias" title="可编辑的识别规则表（显示名=别名）">识别规则</button>'
      + '<button class="qdb-btn qdb-btn-mini" type="button" data-write="library-binds-export" title="导出人工绑定表">导出绑定</button>'
      + '<button class="qdb-btn qdb-btn-mini" type="button" data-write="library-binds-import" title="导入人工绑定表">导入绑定</button>'
      + '<button class="qdb-btn qdb-btn-mini" type="button" data-write="library-usage-scan" title="按文件名/目录名扫一遍工程引用">扫描工程</button>'
      + '<button class="qdb-btn qdb-btn-mini" type="button" data-write="library-relocate-undo" title="把最近一次「归位」改回去">撤销归位</button>'
      + '<button class="qdb-btn qdb-btn-mini" type="button" data-write="library-name-find" title="一行一个名字 / 商品号，批量搜出来再绑">按名字找号</button>'
      + '<button class="qdb-btn qdb-btn-mini" type="button" data-write="library-trash-open" title="看回收站里的素材">回收站</button>'
      + cloudAll
