      + '<span class="qdb-dl-chip" id="libProDlChip" hidden></span>'
      + (libProState.cloudUnsupported ? '<span class="qdb-hint" data-tone="warn">后端还没上线「已购未下载」（重启桥接后再试）</span>' : '')
