    return '<article class="qdb-asset qdb-card qdb-libpro-card" data-key="' + esc(a.key) + '"' + (hasManual ? ' data-manual="1"' : '') + ' tabindex="0">'
      + libBatchCheck(a)
      + '<button class="qdb-libpro-fav' + (fav ? ' is-on' : '') + '" type="button" data-libpro-fav="' + esc(a.key)
      + '" aria-pressed="' + (fav ? 'true' : 'false') + '" title="' + (fav ? '取消收藏' : '收藏这件素材') + '">★</button>'
      + '<div class="qdb-libpro-cover" data-write="library-detail" data-key="' + esc(a.key) + '" title="点开看详情">'
      + (Number(a.files) > 1 ? '<span class="qdb-libpro-badge qdb-libpro-files" data-kind="files">' + numText(Number(a.files)) + ' 个文件</span>' : '')
      + cover + '</div>'
      + '<div class="qdb-libpro-body">'
      + '<div class="qdb-libpro-title" data-write="library-detail" data-key="' + esc(a.key) + '" title="'
      + esc([a.title, a.dir].filter(Boolean).join(' · ')) + '">' + esc(shownTitle) + statusBadge + libDupBadge(a) + '</div>'
      + (LIBPRO_PLAIN_NAME_RE.test(shownTitle) && origName
        ? '<div class="qdb-libpro-orig" title="' + esc(String(a.mainName || '')) + '">原名 ' + esc(origName) + '</div>' : '')
      + noteLine
      + '<div class="qdb-libpro-meta"><span class="qdb-libpro-id' + (a.boothId ? '' : ' is-noid') + '">' + idText
      + '</span>' + (shop ? '<span class="qdb-libpro-shop">' + esc(shop) + '</span>' : '') + '</div>'
      + libProSuggestionRow(a)
