      + '<button class="qdb-btn qdb-btn-mini" type="button" data-write="library-find-by-image" data-key="' + esc(a.key)
      + '" data-title="' + esc(a.title || a.mainName || '') + '" title="拿这张封面去 BOOTH 反搜">以图搜源</button>'
